-- Contour reference database schema, version 1.5, 16 October 2026.
-- Executable SQLite structural reference, NOT a Drift migration or encryption proof.
-- Sources: SPEC 9; SYSTEM_DESIGN 5-8, 10, 12-13; USAGE_FLOWS G01-G14.
-- Apply SQLCipher key and verify cipher BEFORE this script in the production vault.
-- Release startup additionally configures WAL, synchronous=FULL and bounded caches.
-- Keep all tables, FTS, staging and temporary processing inside encrypted/local storage.
-- UUID v7 authored IDs; ISO local dates; UTC INTEGER milliseconds; 64-bit minor units.
-- Wall-clock timestamps may go backward; revisions establish concurrency, never time.
-- Decimal codec: normalized base-10 text, <=76 digits, <=38 fractional places.
-- No exponent, leading plus, leading integer zeros, trailing fraction zeros or -0.
-- Validate bindings and all arithmetic in exact domain code; NEVER cast Decimal to REAL.
-- STRICT does not prevent lossless coercion: bind money as checked signed integers.
-- Currency code/digits table is seeded from a bundled versioned catalogue, not a server.
-- Financial gates remain prerequisites. This schema does not define missing formulas.
-- Never use INSERT OR REPLACE for authored, identity, operation or history records.
PRAGMA foreign_keys = ON;
PRAGMA recursive_triggers = ON;
PRAGMA temp_store = MEMORY;
BEGIN;

CREATE TABLE currencies ( code TEXT PRIMARY KEY NOT NULL CHECK (length(CAST(code AS BLOB)) = 3 AND instr(code,char(0)) = 0 AND code NOT GLOB '*[^A-Z]*'), minor_digits INTEGER NOT NULL CHECK (minor_digits BETWEEN 0 AND 6) ) STRICT, WITHOUT ROWID;
-- Currency definitions are pinned. Changed minor-unit meaning requires a separately
-- reviewed migration; it cannot be a catalogue refresh of existing amounts.
CREATE TRIGGER currency_definition_immutable BEFORE UPDATE ON currencies BEGIN SELECT RAISE(ABORT, 'immutable_currency_definition'); END;
-- The external durable generation pointer owns restore identity. This row mirrors it.
CREATE TABLE db_state ( singleton INTEGER PRIMARY KEY CHECK (singleton = 1), db_epoch TEXT NOT NULL CHECK (length(db_epoch) > 0), commit_sequence INTEGER NOT NULL CHECK (commit_sequence >= 0), schema_version INTEGER NOT NULL CHECK (schema_version >= 1), network_policy_epoch INTEGER NOT NULL CHECK (network_policy_epoch >= 0), network_enabled INTEGER NOT NULL DEFAULT 0 CHECK (network_enabled IN (0,1)), read_revision INTEGER NOT NULL DEFAULT 0 CHECK (read_revision >= 0) ) STRICT;
-- Actual identity supertype for audit/draft references. Authored insert triggers populate
-- this registry atomically. Kind is fixed; the single writer verifies subtype existence.
-- Audit retains identity even if the whole vault is later replaced. No polymorphic FK.
CREATE TABLE entity_registry ( id TEXT PRIMARY KEY NOT NULL, entity_kind TEXT NOT NULL CHECK (length(entity_kind) > 0), UNIQUE (id, entity_kind) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER entity_registry_immutable_update BEFORE UPDATE ON entity_registry BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER entity_registry_immutable_delete BEFORE DELETE ON entity_registry BEGIN SELECT RAISE(ABORT, 'retained_history'); END;

-- Intents precede commit. A rejected/cancelled changed draft gets a NEW operation ID.
-- State transitions are conditional on no running writer and a resolved prior outcome.
CREATE TABLE operation_intents ( operation_id TEXT PRIMARY KEY NOT NULL, command_type TEXT NOT NULL CHECK (length(command_type) > 0), payload_digest BLOB NOT NULL CHECK (length(payload_digest) = 32), payload_version INTEGER NOT NULL CHECK (payload_version >= 1), draft_id TEXT, submitted_at INTEGER NOT NULL CHECK (submitted_at >= 0), state TEXT NOT NULL CHECK (state IN ('submitted','running','committed','rejected','cancelled')), state_version INTEGER NOT NULL DEFAULT 1 CHECK (state_version >= 1), safe_error_code TEXT, FOREIGN KEY (draft_id) REFERENCES draft_headers(id) ) STRICT, WITHOUT ROWID;
CREATE INDEX operation_draft_lookup ON operation_intents(draft_id, submitted_at);
CREATE UNIQUE INDEX operation_draft_active ON operation_intents(draft_id) WHERE draft_id IS NOT NULL AND state IN ('submitted','running');
CREATE TRIGGER operation_intent_identity BEFORE UPDATE ON operation_intents WHEN NEW.operation_id IS NOT OLD.operation_id OR NEW.command_type IS NOT OLD.command_type OR NEW.payload_digest IS NOT OLD.payload_digest OR NEW.payload_version IS NOT OLD.payload_version OR NEW.draft_id IS NOT OLD.draft_id OR NEW.submitted_at IS NOT OLD.submitted_at OR NEW.state_version < OLD.state_version + 1 OR OLD.state IN ('committed','rejected','cancelled') OR (OLD.state = 'submitted' AND NEW.state NOT IN ('running','cancelled','rejected')) OR (OLD.state = 'running' AND NEW.state NOT IN ('running','submitted','committed','rejected','cancelled')) BEGIN SELECT RAISE(ABORT, 'invalid_operation_transition'); END;
CREATE TRIGGER operation_intent_retain BEFORE DELETE ON operation_intents BEGIN SELECT RAISE(ABORT, 'retained_operation_identity'); END;
CREATE TABLE operation_receipts ( operation_id TEXT PRIMARY KEY NOT NULL REFERENCES operation_intents(operation_id), commit_sequence INTEGER NOT NULL UNIQUE CHECK (commit_sequence > 0), committed_at INTEGER NOT NULL CHECK (committed_at >= 0), result_version INTEGER NOT NULL CHECK (result_version >= 1), result_json TEXT NOT NULL CHECK (json_valid(result_json) AND length(CAST(result_json AS BLOB)) <= 65536), compensates_operation_id TEXT REFERENCES operation_receipts(operation_id), CHECK (compensates_operation_id IS NULL OR compensates_operation_id <> operation_id) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER operation_receipts_immutable_update BEFORE UPDATE ON operation_receipts BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER operation_receipts_immutable_delete BEFORE DELETE ON operation_receipts BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
-- Frozen, canonical structured command input is durable BEFORE submission.
-- For a large batch, stream bounded chunks; the manifest defines exact order/digests.
-- No raw source bytes, passwords, transcripts or provider credentials are allowed.
-- Writer verifies chunk closure, total bytes, canonical codec and intent payload digest.
-- A prepared execution plan is a derivative of this input and captured revisions;
-- store its bounded rows in encrypted operational staging while preparation is active.
CREATE TABLE operation_payloads ( operation_id TEXT PRIMARY KEY NOT NULL REFERENCES operation_intents(operation_id), codec_version INTEGER NOT NULL CHECK (codec_version >= 1), chunk_count INTEGER NOT NULL CHECK (chunk_count >= 1), total_bytes INTEGER NOT NULL CHECK (total_bytes >= 1), manifest_digest BLOB NOT NULL CHECK (length(manifest_digest) = 32) ) STRICT, WITHOUT ROWID;
CREATE TABLE operation_payload_chunks ( operation_id TEXT NOT NULL REFERENCES operation_payloads(operation_id), chunk_index INTEGER NOT NULL CHECK (chunk_index >= 0), payload_json TEXT NOT NULL CHECK (json_valid(payload_json) AND length(CAST(payload_json AS BLOB)) BETWEEN 1 AND 262144), content_digest BLOB NOT NULL CHECK (length(content_digest) = 32), PRIMARY KEY (operation_id, chunk_index) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER operation_payload_immutable BEFORE UPDATE ON operation_payloads BEGIN SELECT RAISE(ABORT, 'immutable_operation_payload'); END;
CREATE TRIGGER operation_chunk_immutable BEFORE UPDATE ON operation_payload_chunks BEGIN SELECT RAISE(ABORT, 'immutable_operation_payload'); END;
CREATE TRIGGER operation_payload_retain BEFORE DELETE ON operation_payloads WHEN (SELECT state FROM operation_intents WHERE operation_id = OLD.operation_id) NOT IN ('committed','rejected','cancelled') BEGIN SELECT RAISE(ABORT, 'unresolved_operation_payload'); END;
CREATE TRIGGER operation_chunk_retain BEFORE DELETE ON operation_payload_chunks WHEN (SELECT state FROM operation_intents WHERE operation_id = OLD.operation_id) NOT IN ('committed','rejected','cancelled') BEGIN SELECT RAISE(ABORT, 'unresolved_operation_payload'); END;
-- Terminal cleanup removes chunks then manifest; immutable receipt/digest still resolves
-- retry. Uncommitted changed input always gets a new operation ID, never reused bytes.

CREATE TABLE accounts ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('accounts') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 256), type TEXT NOT NULL CHECK (type IN ('bank','cash','wallet','card','brokerage','equityplan','pension','deposit','property','vehicle','preciousMetal','privateFund','privateShares','insuranceCashValue','collectible','loan','paylater','moneyLent','moneyBorrowed','taxDue','other')), currency TEXT NOT NULL REFERENCES currencies(code), institution TEXT CHECK (institution IS NULL OR length(institution) <= 256), is_liability INTEGER NOT NULL CHECK (is_liability IN (0,1)), is_liquid INTEGER NOT NULL CHECK (is_liquid IN (0,1)), include_in_net_worth INTEGER NOT NULL CHECK (include_in_net_worth IN (0,1)), ownership_percent_decimal TEXT NOT NULL DEFAULT '100' CHECK (instr(ownership_percent_decimal, char(0)) = 0 AND typeof(ownership_percent_decimal) = 'text' AND length(ownership_percent_decimal) BETWEEN 1 AND 78 AND ownership_percent_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(ownership_percent_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(ownership_percent_decimal,2),'-') = 0 AND length(ownership_percent_decimal) - length(replace(ownership_percent_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(ownership_percent_decimal,1,1) = '-' THEN substr(ownership_percent_decimal,2) ELSE ownership_percent_decimal END),1,1) BETWEEN '0' AND '9' AND substr(ownership_percent_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(ownership_percent_decimal,1,1) = '-' THEN substr(ownership_percent_decimal,2) ELSE ownership_percent_decimal END) NOT GLOB '0[0-9]*' AND ownership_percent_decimal <> '-0' AND (instr(ownership_percent_decimal,'.') = 0 OR (substr(ownership_percent_decimal,-1) < '0' AND length(ownership_percent_decimal) - instr(ownership_percent_decimal,'.') <= 38)) AND substr(ownership_percent_decimal,1,1) <> '-'), minimum_balance_minor INTEGER, overdraft_limit_minor INTEGER CHECK (overdraft_limit_minor IS NULL OR overdraft_limit_minor >= 0), archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0,1)), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, UNIQUE (id, currency)) STRICT;
CREATE TRIGGER accounts_identity AFTER INSERT ON accounts BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'accounts'); END;
CREATE TRIGGER accounts_revision BEFORE UPDATE ON accounts WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER accounts_retain BEFORE DELETE ON accounts BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE categories ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('categories') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 128), parent_id TEXT REFERENCES categories(id), kind TEXT NOT NULL CHECK (kind IN ('expense','income')), sort_order INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0,1)), CHECK (parent_id IS NULL OR parent_id <> id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER categories_identity AFTER INSERT ON categories BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'categories'); END;
CREATE TRIGGER categories_revision BEFORE UPDATE ON categories WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER categories_retain BEFORE DELETE ON categories BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE financial_events ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('financial_events') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), event_type TEXT NOT NULL CHECK (event_type IN ('payment','income','transfer','refund','investment','vest','payslip','settlement','adjustment','fee')), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), operation_id TEXT NOT NULL REFERENCES operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED, supersedes_event_id TEXT REFERENCES financial_events(id), CHECK (supersedes_event_id IS NULL OR supersedes_event_id <> id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER financial_events_identity AFTER INSERT ON financial_events BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'financial_events'); END;
CREATE TRIGGER financial_events_revision BEFORE UPDATE ON financial_events WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER financial_events_retain BEFORE DELETE ON financial_events BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE transactions ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('transactions') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), event_id TEXT NOT NULL REFERENCES financial_events(id), account_id TEXT NOT NULL, date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), amount_minor INTEGER NOT NULL, currency TEXT NOT NULL REFERENCES currencies(code), kind TEXT NOT NULL CHECK (kind IN ('expense','income','transfer','refund','fee','loanIn','saleProceeds')), merchant_name TEXT CHECK (merchant_name IS NULL OR length(merchant_name) <= 512), note TEXT CHECK (note IS NULL OR length(note) <= 16384), category_id TEXT REFERENCES categories(id), source TEXT NOT NULL CHECK (source IN ('imported','captured','manual','computed')), is_estimated INTEGER NOT NULL DEFAULT 0 CHECK (is_estimated IN (0,1)), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (account_id, currency) REFERENCES accounts(id, currency), UNIQUE (id, currency)) STRICT;
CREATE TRIGGER transactions_identity AFTER INSERT ON transactions BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'transactions'); END;
CREATE TRIGGER transactions_revision BEFORE UPDATE ON transactions WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER transactions_retain BEFORE DELETE ON transactions BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE transaction_splits ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('transaction_splits') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), transaction_id TEXT NOT NULL REFERENCES transactions(id), category_id TEXT REFERENCES categories(id), amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, note TEXT CHECK (note IS NULL OR length(note) <= 16384), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (transaction_id, currency) REFERENCES transactions(id, currency)) STRICT;
CREATE TRIGGER transaction_splits_identity AFTER INSERT ON transaction_splits BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'transaction_splits'); END;
CREATE TRIGGER transaction_splits_revision BEFORE UPDATE ON transaction_splits WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER transaction_splits_retain BEFORE DELETE ON transaction_splits BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
-- A transfer's two principal postings are existing canonical transactions.
-- Domain checks same event, distinct accounts, opposite signs, FX and fee rules (G13).
CREATE TABLE transfer_links ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('transfer_links') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), event_id TEXT NOT NULL REFERENCES financial_events(id), sending_transaction_id TEXT NOT NULL REFERENCES transactions(id), receiving_transaction_id TEXT NOT NULL REFERENCES transactions(id), fee_transaction_id TEXT REFERENCES transactions(id), CHECK (sending_transaction_id <> receiving_transaction_id), CHECK (fee_transaction_id IS NULL OR (fee_transaction_id <> sending_transaction_id AND fee_transaction_id <> receiving_transaction_id)), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER transfer_links_identity AFTER INSERT ON transfer_links BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'transfer_links'); END;
CREATE TRIGGER transfer_links_revision BEFORE UPDATE ON transfer_links WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER transfer_links_retain BEFORE DELETE ON transfer_links BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE UNIQUE INDEX transfer_event_live ON transfer_links(event_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX transfer_sending_live ON transfer_links(sending_transaction_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX transfer_receiving_live ON transfer_links(receiving_transaction_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX transfer_fee_live ON transfer_links(fee_transaction_id) WHERE deleted_at IS NULL AND fee_transaction_id IS NOT NULL;
-- Cross-role exclusivity and same-event/account closure are checked by the command.
CREATE TABLE transfer_fx ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('transfer_fx') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), transfer_link_id TEXT NOT NULL UNIQUE REFERENCES transfer_links(id), executed_rate_decimal TEXT NOT NULL CHECK (instr(executed_rate_decimal, char(0)) = 0 AND typeof(executed_rate_decimal) = 'text' AND length(executed_rate_decimal) BETWEEN 1 AND 78 AND executed_rate_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(executed_rate_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(executed_rate_decimal,2),'-') = 0 AND length(executed_rate_decimal) - length(replace(executed_rate_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(executed_rate_decimal,1,1) = '-' THEN substr(executed_rate_decimal,2) ELSE executed_rate_decimal END),1,1) BETWEEN '0' AND '9' AND substr(executed_rate_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(executed_rate_decimal,1,1) = '-' THEN substr(executed_rate_decimal,2) ELSE executed_rate_decimal END) NOT GLOB '0[0-9]*' AND executed_rate_decimal <> '-0' AND (instr(executed_rate_decimal,'.') = 0 OR (substr(executed_rate_decimal,-1) < '0' AND length(executed_rate_decimal) - instr(executed_rate_decimal,'.') <= 38)) AND substr(executed_rate_decimal,1,1) <> '-' AND executed_rate_decimal <> '0'), comparison_rate_decimal TEXT CHECK (comparison_rate_decimal IS NULL OR (instr(comparison_rate_decimal, char(0)) = 0 AND typeof(comparison_rate_decimal) = 'text' AND length(comparison_rate_decimal) BETWEEN 1 AND 78 AND comparison_rate_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(comparison_rate_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(comparison_rate_decimal,2),'-') = 0 AND length(comparison_rate_decimal) - length(replace(comparison_rate_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(comparison_rate_decimal,1,1) = '-' THEN substr(comparison_rate_decimal,2) ELSE comparison_rate_decimal END),1,1) BETWEEN '0' AND '9' AND substr(comparison_rate_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(comparison_rate_decimal,1,1) = '-' THEN substr(comparison_rate_decimal,2) ELSE comparison_rate_decimal END) NOT GLOB '0[0-9]*' AND comparison_rate_decimal <> '-0' AND (instr(comparison_rate_decimal,'.') = 0 OR (substr(comparison_rate_decimal,-1) < '0' AND length(comparison_rate_decimal) - instr(comparison_rate_decimal,'.') <= 38)) AND substr(comparison_rate_decimal,1,1) <> '-' AND comparison_rate_decimal <> '0')), comparison_rate_date TEXT CHECK (comparison_rate_date IS NULL OR ((length(comparison_rate_date) = 10 AND comparison_rate_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND comparison_rate_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(comparison_rate_date, '+0 days') IS comparison_rate_date))), service TEXT CHECK (service IS NULL OR length(service) <= 256), CHECK ((comparison_rate_decimal IS NULL) = (comparison_rate_date IS NULL)), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER transfer_fx_identity AFTER INSERT ON transfer_fx BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'transfer_fx'); END;
CREATE TRIGGER transfer_fx_revision BEFORE UPDATE ON transfer_fx WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER transfer_fx_retain BEFORE DELETE ON transfer_fx BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE refund_links ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('refund_links') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), refund_transaction_id TEXT NOT NULL REFERENCES transactions(id), original_transaction_id TEXT NOT NULL REFERENCES transactions(id), amount_minor INTEGER NOT NULL CHECK (amount_minor > 0), currency TEXT NOT NULL REFERENCES currencies(code), CHECK (refund_transaction_id <> original_transaction_id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, UNIQUE (refund_transaction_id, original_transaction_id)) STRICT;
CREATE TRIGGER refund_links_identity AFTER INSERT ON refund_links BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'refund_links'); END;
CREATE TRIGGER refund_links_revision BEFORE UPDATE ON refund_links WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER refund_links_retain BEFORE DELETE ON refund_links BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE INDEX tx_account_date_live ON transactions(account_id, date DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX tx_date_live ON transactions(date DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX tx_category_date_live ON transactions(category_id, date DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX tx_kind_date_live ON transactions(kind, date DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX tx_account_kind_date_live ON transactions(account_id, kind, date DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX tx_candidate_live ON transactions(account_id, currency, amount_minor, date, id) WHERE deleted_at IS NULL;
CREATE INDEX tx_event ON transactions(event_id);
CREATE INDEX split_tx ON transaction_splits(transaction_id);
CREATE INDEX split_category_tx ON transaction_splits(category_id, transaction_id) WHERE deleted_at IS NULL;
CREATE INDEX financial_event_operation ON financial_events(operation_id);
-- Content hashes are candidate matches, NEVER a uniqueness claim.
CREATE TABLE transaction_candidate_keys ( transaction_id TEXT PRIMARY KEY NOT NULL REFERENCES transactions(id), content_digest BLOB NOT NULL CHECK (length(content_digest) = 32), normalization_version INTEGER NOT NULL CHECK (normalization_version >= 1) ) STRICT, WITHOUT ROWID;
CREATE INDEX candidate_digest ON transaction_candidate_keys(content_digest, transaction_id);
-- Tuple components are non-null. Account scope is a source namespace token; use an
-- explicit source-wide scope when no account exists. It is not a nullable account FK.
CREATE TABLE source_identities ( id INTEGER PRIMARY KEY, namespace TEXT NOT NULL CHECK (length(namespace) BETWEEN 1 AND 128), account_scope TEXT NOT NULL CHECK (length(account_scope) BETWEEN 1 AND 256), source_record_id TEXT NOT NULL CHECK (length(source_record_id) BETWEEN 1 AND 1024), identity_version INTEGER NOT NULL CHECK (identity_version >= 1), first_seen_at INTEGER NOT NULL CHECK (first_seen_at >= 0), UNIQUE (namespace, account_scope, source_record_id) ) STRICT;
CREATE TRIGGER source_identities_immutable_update BEFORE UPDATE ON source_identities BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER source_identities_immutable_delete BEFORE DELETE ON source_identities BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
CREATE TABLE source_event_links ( source_identity_id INTEGER NOT NULL REFERENCES source_identities(id), event_id TEXT NOT NULL REFERENCES financial_events(id), operation_id TEXT NOT NULL REFERENCES operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED, PRIMARY KEY (source_identity_id, event_id) ) STRICT, WITHOUT ROWID;
-- Use the evidence here to decide the authoritative ledger state BEFORE proposal.
CREATE TABLE balance_anchors ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('balance_anchors') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), account_id TEXT NOT NULL, date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), balance_minor INTEGER NOT NULL, currency TEXT NOT NULL, source TEXT NOT NULL CHECK (source IN ('imported','captured','manual')), source_identity_id INTEGER REFERENCES source_identities(id), inclusive INTEGER NOT NULL DEFAULT 1 CHECK (inclusive = 1), supersedes_anchor_id TEXT REFERENCES balance_anchors(id), CHECK (supersedes_anchor_id IS NULL OR supersedes_anchor_id <> id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (account_id, currency) REFERENCES accounts(id, currency), UNIQUE (account_id, id)) STRICT;
CREATE TRIGGER balance_anchors_identity AFTER INSERT ON balance_anchors BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'balance_anchors'); END;
CREATE TRIGGER balance_anchors_revision BEFORE UPDATE ON balance_anchors WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER balance_anchors_retain BEFORE DELETE ON balance_anchors BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TRIGGER balance_anchors_evidence_immutable BEFORE UPDATE ON balance_anchors WHEN NEW.account_id IS NOT OLD.account_id OR NEW.date IS NOT OLD.date OR NEW.balance_minor IS NOT OLD.balance_minor OR NEW.currency IS NOT OLD.currency OR NEW.source IS NOT OLD.source OR NEW.source_identity_id IS NOT OLD.source_identity_id OR NEW.inclusive IS NOT OLD.inclusive OR NEW.supersedes_anchor_id IS NOT OLD.supersedes_anchor_id BEGIN SELECT RAISE(ABORT, 'immutable_evidence'); END;
-- Technical active selection is recomputable from authored evidence/command history.
-- Selecting/reconciling an anchor is a confirmed command, with audit + dirty range.
CREATE TABLE current_balance_anchors ( account_id TEXT PRIMARY KEY NOT NULL REFERENCES accounts(id), anchor_id TEXT NOT NULL, selected_operation_id TEXT NOT NULL REFERENCES operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (account_id, anchor_id) REFERENCES balance_anchors(account_id, id) ) STRICT, WITHOUT ROWID;
CREATE INDEX anchors_account_date ON balance_anchors(account_id, date DESC, id DESC);
-- Public caches use integer keys. They carry no authored metadata or ChangeLog.
CREATE TABLE market_providers ( id INTEGER PRIMARY KEY, namespace TEXT NOT NULL UNIQUE CHECK (length(namespace) BETWEEN 1 AND 128), adapter_version INTEGER NOT NULL CHECK (adapter_version >= 1) ) STRICT;
CREATE TRIGGER provider_identity BEFORE UPDATE ON market_providers WHEN NEW.id IS NOT OLD.id OR NEW.namespace IS NOT OLD.namespace BEGIN SELECT RAISE(ABORT, 'immutable_provider_identity'); END;
CREATE TABLE public_instruments ( id INTEGER PRIMARY KEY, provider_id INTEGER NOT NULL REFERENCES market_providers(id), provider_instrument_key TEXT NOT NULL CHECK (length(provider_instrument_key) BETWEEN 1 AND 256), exchange TEXT NOT NULL CHECK (length(exchange) BETWEEN 1 AND 64), symbol TEXT NOT NULL CHECK (length(symbol) BETWEEN 1 AND 128), UNIQUE (provider_id, provider_instrument_key), UNIQUE (id, provider_id) ) STRICT;
CREATE TRIGGER instrument_identity BEFORE UPDATE ON public_instruments WHEN NEW.id IS NOT OLD.id OR NEW.provider_id IS NOT OLD.provider_id OR NEW.provider_instrument_key IS NOT OLD.provider_instrument_key BEGIN SELECT RAISE(ABORT, 'immutable_instrument_identity'); END;
CREATE TABLE public_instrument_details ( instrument_id INTEGER NOT NULL REFERENCES public_instruments(id), revision INTEGER NOT NULL CHECK (revision >= 1), fetched_at INTEGER NOT NULL CHECK (fetched_at >= 0), details_json TEXT NOT NULL CHECK (json_valid(details_json) AND length(CAST(details_json AS BLOB)) <= 65536), content_digest BLOB NOT NULL CHECK (length(content_digest) = 32), PRIMARY KEY (instrument_id, revision) ) STRICT, WITHOUT ROWID;
-- Whitelist only public fields in details_json; strip URLs/HTML before persistence.
-- Public observation UPDATE is forbidden; DELETE only after evidence pin checks.
CREATE TRIGGER public_details_immutable BEFORE UPDATE ON public_instrument_details BEGIN SELECT RAISE(ABORT, 'immutable_public_observation'); END;
CREATE TABLE securities ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('securities') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), symbol TEXT NOT NULL CHECK (length(symbol) BETWEEN 1 AND 128), exchange TEXT NOT NULL CHECK (length(exchange) BETWEEN 1 AND 64), name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 256), currency TEXT NOT NULL REFERENCES currencies(code), type TEXT NOT NULL CHECK (type IN ('stock','etf','fund','bond','gold','crypto','cash','other')), asset_class TEXT NOT NULL CHECK (asset_class IN ('stocks','equityEtfs','mutualFunds','bonds','gold','cash','other')), public_instrument_id INTEGER REFERENCES public_instruments(id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER securities_identity AFTER INSERT ON securities BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'securities'); END;
CREATE TRIGGER securities_revision BEFORE UPDATE ON securities WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER securities_retain BEFORE DELETE ON securities BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE market_series ( id INTEGER PRIMARY KEY, instrument_id INTEGER NOT NULL, provider_id INTEGER NOT NULL, basis TEXT NOT NULL CHECK (basis IN ('unadjusted','splitAdjusted','totalReturn')), currency TEXT NOT NULL REFERENCES currencies(code), interval TEXT NOT NULL CHECK (interval = 'daily'), FOREIGN KEY (instrument_id, provider_id) REFERENCES public_instruments(id, provider_id), UNIQUE (instrument_id, provider_id, basis, currency, interval) ) STRICT;
CREATE TRIGGER market_series_identity BEFORE UPDATE ON market_series BEGIN SELECT RAISE(ABORT, 'immutable_series_identity'); END;
CREATE TABLE price_quotes ( id INTEGER PRIMARY KEY, series_id INTEGER NOT NULL REFERENCES market_series(id), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), revision INTEGER NOT NULL CHECK (revision >= 1), price_decimal TEXT NOT NULL CHECK (instr(price_decimal, char(0)) = 0 AND typeof(price_decimal) = 'text' AND length(price_decimal) BETWEEN 1 AND 78 AND price_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(price_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(price_decimal,2),'-') = 0 AND length(price_decimal) - length(replace(price_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(price_decimal,1,1) = '-' THEN substr(price_decimal,2) ELSE price_decimal END),1,1) BETWEEN '0' AND '9' AND substr(price_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(price_decimal,1,1) = '-' THEN substr(price_decimal,2) ELSE price_decimal END) NOT GLOB '0[0-9]*' AND price_decimal <> '-0' AND (instr(price_decimal,'.') = 0 OR (substr(price_decimal,-1) < '0' AND length(price_decimal) - instr(price_decimal,'.') <= 38))), observed_at INTEGER CHECK (observed_at IS NULL OR observed_at >= 0), fetched_at INTEGER NOT NULL CHECK (fetched_at >= 0), content_digest BLOB NOT NULL CHECK (length(content_digest) = 32), UNIQUE (series_id, date, revision), UNIQUE (id, series_id, date) ) STRICT;
CREATE TRIGGER price_quote_immutable BEFORE UPDATE ON price_quotes BEGIN SELECT RAISE(ABORT, 'immutable_public_observation'); END;
CREATE TABLE current_quotes ( series_id INTEGER NOT NULL, date TEXT NOT NULL, quote_id INTEGER NOT NULL UNIQUE, PRIMARY KEY (series_id, date), FOREIGN KEY (quote_id, series_id, date) REFERENCES price_quotes(id, series_id, date) ) STRICT, WITHOUT ROWID;
-- UNIQUE(series_id, date, revision) supports reverse date/revision scans; no duplicate index.
-- This table models daily closes only. Add an audited separate spot/intraday series
-- contract before LatestQuotes support; never insert an intraday quote as a daily close.
CREATE TABLE manual_quotes ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('manual_quotes') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), security_id TEXT NOT NULL REFERENCES securities(id), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), price_decimal TEXT NOT NULL CHECK (instr(price_decimal, char(0)) = 0 AND typeof(price_decimal) = 'text' AND length(price_decimal) BETWEEN 1 AND 78 AND price_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(price_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(price_decimal,2),'-') = 0 AND length(price_decimal) - length(replace(price_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(price_decimal,1,1) = '-' THEN substr(price_decimal,2) ELSE price_decimal END),1,1) BETWEEN '0' AND '9' AND substr(price_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(price_decimal,1,1) = '-' THEN substr(price_decimal,2) ELSE price_decimal END) NOT GLOB '0[0-9]*' AND price_decimal <> '-0' AND (instr(price_decimal,'.') = 0 OR (substr(price_decimal,-1) < '0' AND length(price_decimal) - instr(price_decimal,'.') <= 38))), currency TEXT NOT NULL REFERENCES currencies(code), basis TEXT NOT NULL CHECK (basis IN ('unadjusted','splitAdjusted','totalReturn')), source TEXT NOT NULL CHECK (source IN ('manual','imported')), source_identity_id INTEGER REFERENCES source_identities(id), supersedes_quote_id TEXT REFERENCES manual_quotes(id), CHECK (supersedes_quote_id IS NULL OR supersedes_quote_id <> id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER manual_quotes_identity AFTER INSERT ON manual_quotes BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'manual_quotes'); END;
CREATE TRIGGER manual_quotes_revision BEFORE UPDATE ON manual_quotes WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER manual_quotes_retain BEFORE DELETE ON manual_quotes BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TRIGGER manual_quotes_evidence_immutable BEFORE UPDATE ON manual_quotes WHEN NEW.security_id IS NOT OLD.security_id OR NEW.date IS NOT OLD.date OR NEW.price_decimal IS NOT OLD.price_decimal OR NEW.currency IS NOT OLD.currency OR NEW.basis IS NOT OLD.basis OR NEW.source IS NOT OLD.source OR NEW.source_identity_id IS NOT OLD.source_identity_id OR NEW.supersedes_quote_id IS NOT OLD.supersedes_quote_id BEGIN SELECT RAISE(ABORT, 'immutable_evidence'); END;
CREATE TABLE fx_observations ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('fx_observations') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), base_currency TEXT NOT NULL REFERENCES currencies(code), quote_currency TEXT NOT NULL REFERENCES currencies(code), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), rate_decimal TEXT NOT NULL CHECK (instr(rate_decimal, char(0)) = 0 AND typeof(rate_decimal) = 'text' AND length(rate_decimal) BETWEEN 1 AND 78 AND rate_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(rate_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(rate_decimal,2),'-') = 0 AND length(rate_decimal) - length(replace(rate_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(rate_decimal,1,1) = '-' THEN substr(rate_decimal,2) ELSE rate_decimal END),1,1) BETWEEN '0' AND '9' AND substr(rate_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(rate_decimal,1,1) = '-' THEN substr(rate_decimal,2) ELSE rate_decimal END) NOT GLOB '0[0-9]*' AND rate_decimal <> '-0' AND (instr(rate_decimal,'.') = 0 OR (substr(rate_decimal,-1) < '0' AND length(rate_decimal) - instr(rate_decimal,'.') <= 38)) AND substr(rate_decimal,1,1) <> '-' AND rate_decimal <> '0'), source TEXT NOT NULL CHECK (source IN ('manual','imported')), source_identity_id INTEGER REFERENCES source_identities(id), supersedes_fx_id TEXT REFERENCES fx_observations(id), CHECK (base_currency <> quote_currency), CHECK (supersedes_fx_id IS NULL OR supersedes_fx_id <> id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER fx_observations_identity AFTER INSERT ON fx_observations BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'fx_observations'); END;
CREATE TRIGGER fx_observations_revision BEFORE UPDATE ON fx_observations WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER fx_observations_retain BEFORE DELETE ON fx_observations BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TRIGGER fx_observations_evidence_immutable BEFORE UPDATE ON fx_observations WHEN NEW.base_currency IS NOT OLD.base_currency OR NEW.quote_currency IS NOT OLD.quote_currency OR NEW.date IS NOT OLD.date OR NEW.rate_decimal IS NOT OLD.rate_decimal OR NEW.source IS NOT OLD.source OR NEW.source_identity_id IS NOT OLD.source_identity_id OR NEW.supersedes_fx_id IS NOT OLD.supersedes_fx_id BEGIN SELECT RAISE(ABORT, 'immutable_evidence'); END;
CREATE INDEX manual_quote_lookup ON manual_quotes(security_id, basis, date DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX fx_lookup ON fx_observations(base_currency, quote_currency, date DESC, id DESC) WHERE deleted_at IS NULL;
CREATE TABLE holdings ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('holdings') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), account_id TEXT NOT NULL REFERENCES accounts(id), security_id TEXT NOT NULL REFERENCES securities(id), cost_method TEXT NOT NULL CHECK (cost_method IN ('average','fifo')), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER holdings_identity AFTER INSERT ON holdings BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'holdings'); END;
CREATE TRIGGER holdings_revision BEFORE UPDATE ON holdings WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER holdings_retain BEFORE DELETE ON holdings BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE UNIQUE INDEX holding_live ON holdings(account_id, security_id) WHERE deleted_at IS NULL;
-- Holding quantity is derived from accepted events/observations, not a second ledger.
CREATE TABLE investment_transactions ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('investment_transactions') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), event_id TEXT NOT NULL REFERENCES financial_events(id), holding_id TEXT NOT NULL REFERENCES holdings(id), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), type TEXT NOT NULL CHECK (type IN ('buy','sell','dividend','interest','drip','dividendInKind','split','transferIn','transferOut','vest','esppPurchase','fee','returnOfCapital','stakingReward')), effective_at INTEGER CHECK (effective_at IS NULL OR effective_at >= 0), order_sequence INTEGER CHECK (order_sequence IS NULL OR order_sequence >= 0), order_scope TEXT CHECK (order_scope IS NULL OR length(CAST(order_scope AS BLOB)) BETWEEN 1 AND 256), order_source TEXT NOT NULL DEFAULT 'unknown' CHECK (order_source IN ('unknown','sourceSequence','effectiveInstant','userConfirmed')), quantity_decimal TEXT CHECK (quantity_decimal IS NULL OR (instr(quantity_decimal, char(0)) = 0 AND typeof(quantity_decimal) = 'text' AND length(quantity_decimal) BETWEEN 1 AND 78 AND quantity_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(quantity_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(quantity_decimal,2),'-') = 0 AND length(quantity_decimal) - length(replace(quantity_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END),1,1) BETWEEN '0' AND '9' AND substr(quantity_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END) NOT GLOB '0[0-9]*' AND quantity_decimal <> '-0' AND (instr(quantity_decimal,'.') = 0 OR (substr(quantity_decimal,-1) < '0' AND length(quantity_decimal) - instr(quantity_decimal,'.') <= 38)) AND quantity_decimal <> '0')), price_decimal TEXT CHECK (price_decimal IS NULL OR (instr(price_decimal, char(0)) = 0 AND typeof(price_decimal) = 'text' AND length(price_decimal) BETWEEN 1 AND 78 AND price_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(price_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(price_decimal,2),'-') = 0 AND length(price_decimal) - length(replace(price_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(price_decimal,1,1) = '-' THEN substr(price_decimal,2) ELSE price_decimal END),1,1) BETWEEN '0' AND '9' AND substr(price_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(price_decimal,1,1) = '-' THEN substr(price_decimal,2) ELSE price_decimal END) NOT GLOB '0[0-9]*' AND price_decimal <> '-0' AND (instr(price_decimal,'.') = 0 OR (substr(price_decimal,-1) < '0' AND length(price_decimal) - instr(price_decimal,'.') <= 38)))), amount_minor INTEGER, fee_minor INTEGER CHECK (fee_minor IS NULL OR fee_minor >= 0), tax_minor INTEGER CHECK (tax_minor IS NULL OR tax_minor >= 0), currency TEXT NOT NULL REFERENCES currencies(code), source TEXT NOT NULL CHECK (source IN ('manual','imported','captured')), CHECK ((order_sequence IS NULL) = (order_scope IS NULL)), CHECK ((order_source = 'unknown' AND effective_at IS NULL AND order_sequence IS NULL) OR (order_source IN ('sourceSequence','effectiveInstant','userConfirmed') AND order_sequence IS NOT NULL)), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER investment_transactions_identity AFTER INSERT ON investment_transactions BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'investment_transactions'); END;
CREATE TRIGGER investment_transactions_revision BEFORE UPDATE ON investment_transactions WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER investment_transactions_retain BEFORE DELETE ON investment_transactions BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
-- amount/fee/tax above describe the event, not independent cash postings.
-- G03 commands link all actual cash through transactions in the same financial_event.
CREATE INDEX investment_holding_date ON investment_transactions(holding_id, date, id) WHERE deleted_at IS NULL;
CREATE INDEX investment_event ON investment_transactions(event_id);
CREATE TABLE position_observations ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('position_observations') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), holding_id TEXT NOT NULL REFERENCES holdings(id), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), quantity_decimal TEXT NOT NULL CHECK (instr(quantity_decimal, char(0)) = 0 AND typeof(quantity_decimal) = 'text' AND length(quantity_decimal) BETWEEN 1 AND 78 AND quantity_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(quantity_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(quantity_decimal,2),'-') = 0 AND length(quantity_decimal) - length(replace(quantity_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END),1,1) BETWEEN '0' AND '9' AND substr(quantity_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END) NOT GLOB '0[0-9]*' AND quantity_decimal <> '-0' AND (instr(quantity_decimal,'.') = 0 OR (substr(quantity_decimal,-1) < '0' AND length(quantity_decimal) - instr(quantity_decimal,'.') <= 38)) AND substr(quantity_decimal,1,1) <> '-' AND quantity_decimal <> '0'), value_minor INTEGER, currency TEXT NOT NULL REFERENCES currencies(code), value_state TEXT NOT NULL CHECK (value_state IN ('known','estimated','missing')), source TEXT NOT NULL CHECK (source IN ('manual','imported','captured')), source_identity_id INTEGER REFERENCES source_identities(id), supersedes_observation_id TEXT REFERENCES position_observations(id), CHECK ((value_state = 'missing' AND value_minor IS NULL) OR (value_state IN ('known','estimated') AND value_minor IS NOT NULL)), CHECK (supersedes_observation_id IS NULL OR supersedes_observation_id <> id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER position_observations_identity AFTER INSERT ON position_observations BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'position_observations'); END;
CREATE TRIGGER position_observations_revision BEFORE UPDATE ON position_observations WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER position_observations_retain BEFORE DELETE ON position_observations BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TRIGGER position_observations_evidence_immutable BEFORE UPDATE ON position_observations WHEN NEW.holding_id IS NOT OLD.holding_id OR NEW.date IS NOT OLD.date OR NEW.quantity_decimal IS NOT OLD.quantity_decimal OR NEW.value_minor IS NOT OLD.value_minor OR NEW.currency IS NOT OLD.currency OR NEW.value_state IS NOT OLD.value_state OR NEW.source IS NOT OLD.source OR NEW.source_identity_id IS NOT OLD.source_identity_id OR NEW.supersedes_observation_id IS NOT OLD.supersedes_observation_id BEGIN SELECT RAISE(ABORT, 'immutable_evidence'); END;
CREATE TABLE lots ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('lots') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), holding_id TEXT NOT NULL REFERENCES holdings(id), acquisition_event_id TEXT NOT NULL REFERENCES investment_transactions(id), acquired_date TEXT NOT NULL CHECK ((length(acquired_date) = 10 AND acquired_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND acquired_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(acquired_date, '+0 days') IS acquired_date)), quantity_decimal TEXT NOT NULL CHECK (instr(quantity_decimal, char(0)) = 0 AND typeof(quantity_decimal) = 'text' AND length(quantity_decimal) BETWEEN 1 AND 78 AND quantity_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(quantity_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(quantity_decimal,2),'-') = 0 AND length(quantity_decimal) - length(replace(quantity_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END),1,1) BETWEEN '0' AND '9' AND substr(quantity_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END) NOT GLOB '0[0-9]*' AND quantity_decimal <> '-0' AND (instr(quantity_decimal,'.') = 0 OR (substr(quantity_decimal,-1) < '0' AND length(quantity_decimal) - instr(quantity_decimal,'.') <= 38)) AND substr(quantity_decimal,1,1) <> '-' AND quantity_decimal <> '0'), cost_minor INTEGER, currency TEXT NOT NULL REFERENCES currencies(code), cost_state TEXT NOT NULL CHECK (cost_state IN ('known','missing')), purchase_fx_id TEXT REFERENCES fx_observations(id), supersedes_lot_id TEXT REFERENCES lots(id), CHECK ((cost_state = 'missing' AND cost_minor IS NULL) OR (cost_state = 'known' AND cost_minor IS NOT NULL)), CHECK (supersedes_lot_id IS NULL OR supersedes_lot_id <> id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER lots_identity AFTER INSERT ON lots BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'lots'); END;
CREATE TRIGGER lots_revision BEFORE UPDATE ON lots WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER lots_retain BEFORE DELETE ON lots BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TRIGGER lots_evidence_immutable BEFORE UPDATE ON lots WHEN NEW.holding_id IS NOT OLD.holding_id OR NEW.acquisition_event_id IS NOT OLD.acquisition_event_id OR NEW.acquired_date IS NOT OLD.acquired_date OR NEW.quantity_decimal IS NOT OLD.quantity_decimal OR NEW.cost_minor IS NOT OLD.cost_minor OR NEW.currency IS NOT OLD.currency OR NEW.cost_state IS NOT OLD.cost_state OR NEW.purchase_fx_id IS NOT OLD.purchase_fx_id OR NEW.supersedes_lot_id IS NOT OLD.supersedes_lot_id BEGIN SELECT RAISE(ABORT, 'immutable_evidence'); END;
-- Automatic FIFO/average results, not authored facts. Acquisition Lots and disposal
-- events remain authored; a backdated edit invalidates these outputs, not source facts.
CREATE TABLE lot_allocations ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, disposal_event_id TEXT NOT NULL REFERENCES investment_transactions(id), lot_id TEXT NOT NULL REFERENCES lots(id), quantity_decimal TEXT NOT NULL CHECK (instr(quantity_decimal, char(0)) = 0 AND typeof(quantity_decimal) = 'text' AND length(quantity_decimal) BETWEEN 1 AND 78 AND quantity_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(quantity_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(quantity_decimal,2),'-') = 0 AND length(quantity_decimal) - length(replace(quantity_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END),1,1) BETWEEN '0' AND '9' AND substr(quantity_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END) NOT GLOB '0[0-9]*' AND quantity_decimal <> '-0' AND (instr(quantity_decimal,'.') = 0 OR (substr(quantity_decimal,-1) < '0' AND length(quantity_decimal) - instr(quantity_decimal,'.') <= 38)) AND substr(quantity_decimal,1,1) <> '-' AND quantity_decimal <> '0'), cost_minor INTEGER, currency TEXT NOT NULL REFERENCES currencies(code), cost_state TEXT NOT NULL CHECK (cost_state IN ('known','missing')), method_version INTEGER NOT NULL CHECK (method_version >= 1), PRIMARY KEY (generation_id, disposal_event_id, lot_id), CHECK ((cost_state = 'missing' AND cost_minor IS NULL) OR (cost_state = 'known' AND cost_minor IS NOT NULL)) ) STRICT, WITHOUT ROWID;
CREATE INDEX lot_holding_date ON lots(holding_id, acquired_date, id) WHERE deleted_at IS NULL;
CREATE INDEX allocation_lot ON lot_allocations(lot_id, generation_id, disposal_event_id);
CREATE INDEX position_observation_holding ON position_observations(holding_id, date DESC, id DESC);
CREATE TABLE schedules ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('schedules') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 256), kind TEXT NOT NULL CHECK (kind IN ('bill','subscription','income','investment','premium','emi','transfer','vest','tax','dividend','oneOff')), account_id TEXT REFERENCES accounts(id), amount_minor INTEGER, currency TEXT NOT NULL REFERENCES currencies(code), amount_state TEXT NOT NULL CHECK (amount_state IN ('known','estimated','missing')), start_date TEXT NOT NULL CHECK ((length(start_date) = 10 AND start_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND start_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(start_date, '+0 days') IS start_date)), end_date TEXT CHECK (end_date IS NULL OR ((length(end_date) = 10 AND end_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND end_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(end_date, '+0 days') IS end_date))), rrule TEXT CHECK (rrule IS NULL OR length(rrule) <= 4096), is_one_off INTEGER NOT NULL CHECK (is_one_off IN (0,1)), CHECK (end_date IS NULL OR end_date >= start_date), CHECK ((is_one_off = 1 AND rrule IS NULL) OR (is_one_off = 0 AND rrule IS NOT NULL)), CHECK ((amount_state = 'missing' AND amount_minor IS NULL) OR (amount_state IN ('known','estimated') AND amount_minor IS NOT NULL)), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER schedules_identity AFTER INSERT ON schedules BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'schedules'); END;
CREATE TRIGGER schedules_revision BEFORE UPDATE ON schedules WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER schedules_retain BEFORE DELETE ON schedules BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
-- Retained operational proposal identity; accepted state lives in decisions.
CREATE TABLE scheduled_occurrences ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('scheduled_occurrences') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), schedule_id TEXT NOT NULL REFERENCES schedules(id), schedule_revision INTEGER NOT NULL CHECK (schedule_revision >= 1), occurrence_key TEXT NOT NULL CHECK (length(occurrence_key) BETWEEN 1 AND 128), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), amount_minor INTEGER, currency TEXT NOT NULL REFERENCES currencies(code), amount_state TEXT NOT NULL CHECK (amount_state IN ('known','estimated','missing')), status TEXT NOT NULL CHECK (status = 'expected'), CHECK ((amount_state = 'missing' AND amount_minor IS NULL) OR (amount_state IN ('known','estimated') AND amount_minor IS NOT NULL)), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, UNIQUE (schedule_id, occurrence_key), UNIQUE (schedule_id, id)) STRICT;
CREATE TRIGGER scheduled_occurrences_identity AFTER INSERT ON scheduled_occurrences BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'scheduled_occurrences'); END;
CREATE TRIGGER scheduled_occurrences_revision BEFORE UPDATE ON scheduled_occurrences WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER scheduled_occurrences_retain BEFORE DELETE ON scheduled_occurrences BEGIN SELECT RAISE(ABORT, 'retained_occurrence_identity'); END;
-- occurrence_key identifies the nominal occurrence independent of rule edits.
-- Re-generation reuses identity; it never converts Expected into an actual posting.
-- Canonical obligations prevent duplicate forecast subtraction across source aliases.
CREATE TRIGGER occurrence_identity_immutable BEFORE UPDATE ON scheduled_occurrences WHEN NEW.schedule_id IS NOT OLD.schedule_id OR NEW.occurrence_key IS NOT OLD.occurrence_key BEGIN SELECT RAISE(ABORT, 'immutable_occurrence_identity'); END;
CREATE TABLE occurrence_locators ( schedule_id TEXT NOT NULL REFERENCES schedules(id), rule_revision INTEGER NOT NULL CHECK (rule_revision >= 1), generator_version INTEGER NOT NULL CHECK (generator_version >= 1), nominal_slot TEXT NOT NULL CHECK (length(CAST(nominal_slot AS BLOB)) BETWEEN 1 AND 256 AND instr(nominal_slot,char(0)) = 0), occurrence_id TEXT NOT NULL, FOREIGN KEY (schedule_id, occurrence_id) REFERENCES scheduled_occurrences(schedule_id, id), UNIQUE (schedule_id, rule_revision, generator_version, occurrence_id), PRIMARY KEY (schedule_id, rule_revision, generator_version, nominal_slot) ) STRICT, WITHOUT ROWID;
CREATE INDEX occurrence_locator_target ON occurrence_locators(occurrence_id);
CREATE TRIGGER occurrence_locator_immutable_update BEFORE UPDATE ON occurrence_locators BEGIN SELECT RAISE(ABORT, 'immutable_occurrence_locator'); END;
CREATE TRIGGER occurrence_locator_immutable_delete BEFORE DELETE ON occurrence_locators BEGIN SELECT RAISE(ABORT, 'retained_occurrence_locator'); END;
CREATE TABLE obligations ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('obligations') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), account_id TEXT REFERENCES accounts(id), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), direction TEXT NOT NULL CHECK (direction IN ('in','out')), amount_minor INTEGER CHECK (amount_minor IS NULL OR amount_minor >= 0), currency TEXT NOT NULL REFERENCES currencies(code), amount_state TEXT NOT NULL CHECK (amount_state IN ('known','estimated','missing')), status TEXT NOT NULL CHECK (status IN ('open','settled','cancelled')), CHECK ((amount_state = 'missing' AND amount_minor IS NULL) OR (amount_state IN ('known','estimated') AND amount_minor IS NOT NULL)), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, UNIQUE (id, currency)) STRICT;
CREATE TRIGGER obligations_identity AFTER INSERT ON obligations BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'obligations'); END;
CREATE TRIGGER obligations_revision BEFORE UPDATE ON obligations WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER obligations_retain BEFORE DELETE ON obligations BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE card_statements ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('card_statements') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), account_id TEXT NOT NULL, close_date TEXT NOT NULL CHECK ((length(close_date) = 10 AND close_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND close_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(close_date, '+0 days') IS close_date)), due_date TEXT NOT NULL CHECK ((length(due_date) = 10 AND due_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND due_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(due_date, '+0 days') IS due_date)), full_amount_minor INTEGER NOT NULL CHECK (full_amount_minor >= 0), minimum_minor INTEGER NOT NULL CHECK (minimum_minor >= 0 AND minimum_minor <= full_amount_minor), currency TEXT NOT NULL, source_identity_id INTEGER REFERENCES source_identities(id), supersedes_statement_id TEXT REFERENCES card_statements(id), CHECK (supersedes_statement_id IS NULL OR supersedes_statement_id <> id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (account_id, currency) REFERENCES accounts(id, currency)) STRICT;
CREATE TRIGGER card_statements_identity AFTER INSERT ON card_statements BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'card_statements'); END;
CREATE TRIGGER card_statements_revision BEFORE UPDATE ON card_statements WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER card_statements_retain BEFORE DELETE ON card_statements BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TRIGGER card_statements_evidence_immutable BEFORE UPDATE ON card_statements WHEN NEW.account_id IS NOT OLD.account_id OR NEW.close_date IS NOT OLD.close_date OR NEW.due_date IS NOT OLD.due_date OR NEW.full_amount_minor IS NOT OLD.full_amount_minor OR NEW.minimum_minor IS NOT OLD.minimum_minor OR NEW.currency IS NOT OLD.currency OR NEW.source_identity_id IS NOT OLD.source_identity_id OR NEW.supersedes_statement_id IS NOT OLD.supersedes_statement_id BEGIN SELECT RAISE(ABORT, 'immutable_evidence'); END;
CREATE TABLE occurrence_obligations ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('occurrence_obligations') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), occurrence_id TEXT NOT NULL UNIQUE REFERENCES scheduled_occurrences(id), obligation_id TEXT NOT NULL REFERENCES obligations(id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER occurrence_obligations_identity AFTER INSERT ON occurrence_obligations BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'occurrence_obligations'); END;
CREATE TRIGGER occurrence_obligations_revision BEFORE UPDATE ON occurrence_obligations WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER occurrence_obligations_retain BEFORE DELETE ON occurrence_obligations BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE card_statement_obligations ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('card_statement_obligations') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), statement_id TEXT NOT NULL UNIQUE REFERENCES card_statements(id), obligation_id TEXT NOT NULL REFERENCES obligations(id), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TRIGGER card_statement_obligations_identity AFTER INSERT ON card_statement_obligations BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'card_statement_obligations'); END;
CREATE TRIGGER card_statement_obligations_revision BEFORE UPDATE ON card_statement_obligations WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER card_statement_obligations_retain BEFORE DELETE ON card_statement_obligations BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE settlement_allocations ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('settlement_allocations') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), obligation_id TEXT NOT NULL, transaction_id TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK (amount_minor > 0), currency TEXT NOT NULL REFERENCES currencies(code), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (obligation_id, currency) REFERENCES obligations(id, currency), FOREIGN KEY (transaction_id, currency) REFERENCES transactions(id, currency)) STRICT;
CREATE TRIGGER settlement_allocations_identity AFTER INSERT ON settlement_allocations BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'settlement_allocations'); END;
CREATE TRIGGER settlement_allocations_revision BEFORE UPDATE ON settlement_allocations WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER settlement_allocations_retain BEFORE DELETE ON settlement_allocations BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
-- Retained operational Expected proposals carry stable IDs, but no automatic
-- ChangeLog. Authored decisions below select overlays; the generator cannot
-- alter a decided proposal or create a canonical obligation/actual posting.
CREATE TABLE occurrence_decisions ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('occurrence_decisions') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), occurrence_id TEXT NOT NULL REFERENCES scheduled_occurrences(id), operation_id TEXT NOT NULL REFERENCES operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED, decision_type TEXT NOT NULL CHECK (decision_type IN ('accepted','edited','skipped','matched','cancelled')), account_id TEXT REFERENCES accounts(id), effective_date TEXT CHECK (effective_date IS NULL OR ((length(effective_date) = 10 AND effective_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND effective_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(effective_date, '+0 days') IS effective_date))), amount_minor INTEGER CHECK (amount_minor IS NULL OR amount_minor >= 0), currency TEXT REFERENCES currencies(code), amount_state TEXT NOT NULL CHECK (amount_state IN ('unchanged','known','estimated','missing')), obligation_id TEXT REFERENCES obligations(id), settlement_allocation_id TEXT REFERENCES settlement_allocations(id), supersedes_decision_id TEXT, CHECK ((amount_state = 'unchanged' AND amount_minor IS NULL AND currency IS NULL) OR (amount_state IN ('known','estimated') AND amount_minor IS NOT NULL AND currency IS NOT NULL) OR (amount_state = 'missing' AND amount_minor IS NULL AND currency IS NOT NULL)), CHECK (settlement_allocation_id IS NULL OR obligation_id IS NOT NULL), FOREIGN KEY (id, entity_kind) REFERENCES entity_registry(id, entity_kind) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (occurrence_id, supersedes_decision_id) REFERENCES occurrence_decisions(occurrence_id, id), UNIQUE (occurrence_id, id) ) STRICT;
CREATE TRIGGER occurrence_decision_identity AFTER INSERT ON occurrence_decisions BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'occurrence_decisions'); END;
CREATE TRIGGER occurrence_decision_immutable_update BEFORE UPDATE ON occurrence_decisions BEGIN SELECT RAISE(ABORT, 'immutable_occurrence_decision'); END;
CREATE TRIGGER occurrence_decision_immutable_delete BEFORE DELETE ON occurrence_decisions BEGIN SELECT RAISE(ABORT, 'retained_occurrence_decision'); END;
CREATE TABLE current_occurrence_decisions ( occurrence_id TEXT PRIMARY KEY NOT NULL REFERENCES scheduled_occurrences(id), decision_id TEXT NOT NULL, selected_operation_id TEXT NOT NULL REFERENCES operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (occurrence_id, decision_id) REFERENCES occurrence_decisions(occurrence_id, id) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER decided_occurrence_frozen BEFORE UPDATE ON scheduled_occurrences WHEN EXISTS (SELECT 1 FROM current_occurrence_decisions WHERE occurrence_id=OLD.id) BEGIN SELECT RAISE(ABORT, 'decided_occurrence_requires_new_decision'); END;
CREATE UNIQUE INDEX settlement_pair_live ON settlement_allocations(obligation_id, transaction_id) WHERE deleted_at IS NULL;
CREATE INDEX settlement_transaction ON settlement_allocations(transaction_id);
CREATE INDEX occurrence_date_live ON scheduled_occurrences(date, id) WHERE deleted_at IS NULL;
CREATE INDEX obligation_due_live ON obligations(date, id) WHERE deleted_at IS NULL AND status = 'open';
-- Cross-currency settlement requires the explicit FX/event graph; never relabel money.
-- Exact caps per obligation and posting are writer checks, not floating SQL sums.
-- Operational staging has explicit retention; no authored ChangeLog for typing.
CREATE TABLE draft_headers ( id TEXT PRIMARY KEY NOT NULL, form_type TEXT NOT NULL, schema_version INTEGER NOT NULL CHECK (schema_version >= 1), db_epoch TEXT NOT NULL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), edit_revision INTEGER NOT NULL CHECK (edit_revision >= 1), status TEXT NOT NULL CHECK (status IN ('editing','submitted','committed','discarded','unsupported')), committed_operation_id TEXT REFERENCES operation_receipts(operation_id), CHECK ((status = 'committed' AND committed_operation_id IS NOT NULL) OR (status <> 'committed' AND committed_operation_id IS NULL)) ) STRICT, WITHOUT ROWID;
CREATE TABLE draft_payloads ( draft_id TEXT PRIMARY KEY NOT NULL REFERENCES draft_headers(id), payload_json TEXT NOT NULL CHECK (json_valid(payload_json) AND length(CAST(payload_json AS BLOB)) <= 262144) ) STRICT, WITHOUT ROWID;
CREATE TABLE draft_references ( draft_id TEXT NOT NULL REFERENCES draft_headers(id), entity_id TEXT NOT NULL REFERENCES entity_registry(id), expected_revision INTEGER NOT NULL CHECK (expected_revision >= 1), PRIMARY KEY (draft_id, entity_id) ) STRICT, WITHOUT ROWID;
-- Save/Discard deletes payload/references atomically, retaining small intent-linked header.
-- User drafts have no automatic expiry. Unsupported schema exposes a recoverable state.
CREATE TABLE import_batches ( id TEXT PRIMARY KEY NOT NULL, parse_config_id TEXT NOT NULL REFERENCES import_parse_configs(id), source TEXT NOT NULL CHECK (source IN ('localFile','localShare','localFolder','financeKit','notification')), file_digest BLOB CHECK (file_digest IS NULL OR length(file_digest) = 32), parser_id TEXT NOT NULL, parser_version INTEGER NOT NULL CHECK (parser_version >= 1), template_version INTEGER, created_at INTEGER NOT NULL CHECK (created_at >= 0), status TEXT NOT NULL CHECK (status IN ('parsing','review','done','discarded','failed','sourceNeeded','unsupportedParser')), row_count INTEGER NOT NULL DEFAULT 0 CHECK (row_count >= 0), parsed_cursor TEXT, safe_error_code TEXT, payload_schema_version INTEGER NOT NULL CHECK (payload_schema_version >= 1) ) STRICT, WITHOUT ROWID;
CREATE INDEX import_file_digest ON import_batches(file_digest);
CREATE TRIGGER import_batch_configuration BEFORE UPDATE ON import_batches WHEN NEW.parse_config_id IS NOT OLD.parse_config_id OR NEW.parser_id IS NOT OLD.parser_id OR NEW.parser_version IS NOT OLD.parser_version OR NEW.template_version IS NOT OLD.template_version OR NEW.file_digest IS NOT OLD.file_digest OR NEW.source IS NOT OLD.source BEGIN SELECT RAISE(ABORT, 'immutable_batch_configuration'); END;
CREATE TABLE staged_rows ( id INTEGER PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES import_batches(id), row_ordinal INTEGER NOT NULL CHECK (row_ordinal >= 0), source_identity_id INTEGER NOT NULL REFERENCES source_identities(id), payload_json TEXT NOT NULL CHECK (json_valid(payload_json) AND length(CAST(payload_json AS BLOB)) <= 262144), payload_schema_version INTEGER NOT NULL CHECK (payload_schema_version >= 1), UNIQUE (batch_id, row_ordinal), UNIQUE (batch_id, source_identity_id) ) STRICT;
CREATE TABLE source_claims ( source_identity_id INTEGER PRIMARY KEY REFERENCES source_identities(id), batch_id TEXT REFERENCES import_batches(id), draft_id TEXT REFERENCES draft_headers(id), status TEXT NOT NULL CHECK (status IN ('staged','accepted','discarded','undone')), decided_operation_id TEXT REFERENCES operation_receipts(operation_id), CHECK ((batch_id IS NOT NULL) + (draft_id IS NOT NULL) = 1), CHECK ((status IN ('accepted','undone') AND decided_operation_id IS NOT NULL) OR status IN ('staged','discarded')) ) STRICT;
-- Claims survive Undo. Retry consults claim/history; equal-content records can coexist.
CREATE TABLE inbox_items ( id INTEGER PRIMARY KEY, source_identity_id INTEGER NOT NULL UNIQUE REFERENCES source_identities(id), staged_row_id INTEGER REFERENCES staged_rows(id), received_at INTEGER NOT NULL CHECK (received_at >= 0), suggestion_type TEXT NOT NULL CHECK (suggestion_type IN ('new','merge','transfer','refund','recurring','categoryChange','vestConfirm','payslipMismatch')), payload_schema_version INTEGER NOT NULL CHECK (payload_schema_version >= 1), proposed_json TEXT CHECK (proposed_json IS NULL OR (json_valid(proposed_json) AND length(CAST(proposed_json AS BLOB)) <= 262144)), decision TEXT NOT NULL CHECK (decision IN ('pending','accepted','deleted')), edit_revision INTEGER NOT NULL CHECK (edit_revision >= 1), decided_at INTEGER, operation_id TEXT REFERENCES operation_receipts(operation_id), CHECK ((decision = 'pending' AND proposed_json IS NOT NULL AND decided_at IS NULL AND operation_id IS NULL) OR (decision = 'accepted' AND decided_at IS NOT NULL AND operation_id IS NOT NULL) OR (decision = 'deleted' AND decided_at IS NOT NULL)) ) STRICT;
CREATE INDEX inbox_pending ON inbox_items(decision, received_at, id);
-- Confirm resolves all selected Inbox effects in ONE transaction or none.
CREATE TABLE change_log ( id INTEGER PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), entity_id TEXT NOT NULL REFERENCES entity_registry(id), from_revision INTEGER CHECK (from_revision IS NULL OR from_revision >= 1), to_revision INTEGER NOT NULL CHECK (to_revision >= 1), change_kind TEXT NOT NULL CHECK (change_kind IN ('create','edit','softDelete','restore','compensate')), before_json TEXT CHECK (before_json IS NULL OR json_valid(before_json)), after_json TEXT NOT NULL CHECK (json_valid(after_json)), schema_version INTEGER NOT NULL CHECK (schema_version >= 1), timestamp INTEGER NOT NULL CHECK (timestamp >= 0), UNIQUE (operation_id, ordinal), CHECK ((from_revision IS NULL AND to_revision = 1) OR (from_revision IS NOT NULL AND to_revision = from_revision + 1)) ) STRICT;
CREATE INDEX change_entity_revision ON change_log(entity_id, to_revision);
CREATE INDEX change_operation ON change_log(operation_id, ordinal);
CREATE TRIGGER change_log_immutable_update BEFORE UPDATE ON change_log BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER change_log_immutable_delete BEFORE DELETE ON change_log BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
-- Attachment bytes are authenticated encrypted immutable files. These are opaque
-- relative object IDs, not external paths. No plaintext keys or credential fields.
CREATE TABLE attachment_manifests ( id TEXT PRIMARY KEY NOT NULL, object_name TEXT NOT NULL UNIQUE CHECK (length(CAST(object_name AS BLOB)) BETWEEN 16 AND 128 AND instr(object_name,char(0)) = 0 AND object_name NOT GLOB '*[^a-zA-Z0-9_-]*'), media_type TEXT NOT NULL, plaintext_size INTEGER NOT NULL CHECK (plaintext_size >= 0), ciphertext_size INTEGER NOT NULL CHECK (ciphertext_size >= 0), authenticated_digest BLOB NOT NULL CHECK (length(authenticated_digest) = 32), encryption_format_version INTEGER NOT NULL CHECK (encryption_format_version >= 1), file_key_reference TEXT NOT NULL, wrapping_key_version INTEGER NOT NULL CHECK (wrapping_key_version >= 1), created_at INTEGER NOT NULL CHECK (created_at >= 0) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER attachment_immutable BEFORE UPDATE ON attachment_manifests BEGIN SELECT RAISE(ABORT, 'immutable_attachment_manifest'); END;
CREATE TABLE event_attachments ( event_id TEXT NOT NULL REFERENCES financial_events(id), attachment_id TEXT NOT NULL REFERENCES attachment_manifests(id), operation_id TEXT NOT NULL REFERENCES operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED, PRIMARY KEY (event_id, attachment_id) ) STRICT, WITHOUT ROWID;
CREATE TABLE draft_attachments ( draft_id TEXT NOT NULL REFERENCES draft_headers(id), attachment_id TEXT NOT NULL REFERENCES attachment_manifests(id), PRIMARY KEY (draft_id, attachment_id) ) STRICT, WITHOUT ROWID;
-- Snapshot manifests/key leases live in the durable generation manager, not only this
-- replaceable DB. Retained generation references block file/key collection globally.
CREATE TRIGGER event_attachments_immutable_update BEFORE UPDATE ON event_attachments BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER event_attachments_immutable_delete BEFORE DELETE ON event_attachments BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
CREATE TABLE dependency_scopes ( id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('account','security','fxPair','schedule','source','settings','clock')), scope_key TEXT NOT NULL CHECK (length(scope_key) > 0), UNIQUE (kind, scope_key) ) STRICT;
CREATE TRIGGER dependency_scope_identity BEFORE UPDATE ON dependency_scopes BEGIN SELECT RAISE(ABORT, 'immutable_dependency_scope'); END;
CREATE TABLE dependency_revisions ( scope_id INTEGER PRIMARY KEY REFERENCES dependency_scopes(id), revision INTEGER NOT NULL CHECK (revision >= 0) ) STRICT;
CREATE TRIGGER dependency_monotonic BEFORE UPDATE ON dependency_revisions WHEN NEW.scope_id IS NOT OLD.scope_id OR NEW.revision <= OLD.revision BEGIN SELECT RAISE(ABORT, 'non_monotonic_dependency'); END;
CREATE TABLE dirty_ranges ( scope_id INTEGER NOT NULL REFERENCES dependency_scopes(id), projection_kind TEXT NOT NULL, start_date TEXT NOT NULL CHECK ((length(start_date) = 10 AND start_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND start_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(start_date, '+0 days') IS start_date)), end_date TEXT CHECK (end_date IS NULL OR ((length(end_date) = 10 AND end_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND end_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(end_date, '+0 days') IS end_date))), required_revision INTEGER NOT NULL CHECK (required_revision >= 1), PRIMARY KEY (scope_id, projection_kind), CHECK (end_date IS NULL OR end_date >= start_date) ) STRICT, WITHOUT ROWID;
-- NULL end means onward. Coalesce conservatively. Delete only if the published result
-- covers the entire CURRENT envelope and the current required revision still matches.
-- Partial work leaves the envelope dirty; stale jobs cannot clear newer/broader work.
CREATE TABLE projection_keys ( id INTEGER PRIMARY KEY, kind TEXT NOT NULL, scope_hash BLOB NOT NULL CHECK (length(scope_hash) = 32), scope_json TEXT NOT NULL CHECK (json_valid(scope_json) AND length(CAST(scope_json AS BLOB)) <= 65536), period_start TEXT NOT NULL CHECK (((length(period_start) = 10 AND period_start GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND period_start BETWEEN '0001-01-01' AND '9999-12-31' AND date(period_start, '+0 days') IS period_start))), period_end TEXT NOT NULL CHECK (((length(period_end) = 10 AND period_end GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND period_end BETWEEN '0001-01-01' AND '9999-12-31' AND date(period_end, '+0 days') IS period_end))), as_of INTEGER NOT NULL CHECK (as_of >= 0), currency TEXT NOT NULL REFERENCES currencies(code), method_version INTEGER NOT NULL CHECK (method_version >= 1), policy_digest BLOB NOT NULL CHECK (length(policy_digest) = 32), policy_json TEXT NOT NULL CHECK (json_valid(policy_json) AND length(CAST(policy_json AS BLOB)) <= 65536), CHECK (period_end >= period_start), UNIQUE (kind, scope_hash, period_start, period_end, currency, method_version, policy_digest) ) STRICT;
CREATE TRIGGER projection_key_identity BEFORE UPDATE ON projection_keys BEGIN SELECT RAISE(ABORT, 'immutable_projection_key'); END;
CREATE TABLE projection_generations ( id INTEGER PRIMARY KEY, key_id INTEGER NOT NULL REFERENCES projection_keys(id), db_epoch TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('staging','published','obsolete','failed')), computed_at INTEGER NOT NULL CHECK (computed_at >= 0), source_commit_sequence INTEGER NOT NULL CHECK (source_commit_sequence >= 0), coverage_json TEXT NOT NULL CHECK (json_valid(coverage_json)), output_row_count INTEGER NOT NULL DEFAULT 0 CHECK (output_row_count >= 0), UNIQUE (id, key_id) ) STRICT;
CREATE TRIGGER generation_transition BEFORE UPDATE ON projection_generations WHEN NEW.id IS NOT OLD.id OR NEW.key_id IS NOT OLD.key_id OR NEW.db_epoch IS NOT OLD.db_epoch OR NOT ((OLD.status='staging' AND NEW.status IN ('staging','published','failed')) OR (OLD.status='published' AND NEW.status='obsolete')) OR (OLD.status<>'staging' AND (NEW.computed_at IS NOT OLD.computed_at OR NEW.source_commit_sequence IS NOT OLD.source_commit_sequence OR NEW.coverage_json IS NOT OLD.coverage_json OR NEW.output_row_count IS NOT OLD.output_row_count)) BEGIN SELECT RAISE(ABORT, 'invalid_generation_transition'); END;
CREATE TRIGGER generation_retire_before_delete BEFORE DELETE ON projection_generations WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT, 'retire_generation_first'); END;
CREATE UNIQUE INDEX projection_one_staging ON projection_generations(key_id) WHERE status='staging';
CREATE INDEX projection_generation_key ON projection_generations(key_id, status, id);
CREATE TABLE projection_inputs ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, scope_id INTEGER NOT NULL REFERENCES dependency_scopes(id), input_revision INTEGER NOT NULL CHECK (input_revision >= 0), PRIMARY KEY (generation_id, scope_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX projection_input_scope ON projection_inputs(scope_id, generation_id);
CREATE TABLE current_projections ( key_id INTEGER PRIMARY KEY REFERENCES projection_keys(id), generation_id INTEGER NOT NULL UNIQUE, FOREIGN KEY (generation_id, key_id) REFERENCES projection_generations(id, key_id) ) STRICT;
-- Publication and pointer switch use one write transaction after epoch/input recheck.
CREATE TABLE projection_quote_inputs ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, quote_id INTEGER NOT NULL REFERENCES price_quotes(id), PRIMARY KEY (generation_id, quote_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX projection_quote_pin ON projection_quote_inputs(quote_id);
CREATE TABLE projection_entity_inputs ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, change_log_id INTEGER NOT NULL REFERENCES change_log(id), PRIMARY KEY (generation_id, change_log_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX projection_entity_pin ON projection_entity_inputs(change_log_id);
-- Freeze consumed operational proposals; they deliberately have no ChangeLog.
-- The complete schedule and selected decision after-images are pinned in this
-- generation. The writer checks their entity kinds, identity and revision.
CREATE TABLE projection_occurrence_inputs ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, occurrence_id TEXT NOT NULL REFERENCES scheduled_occurrences(id), proposal_revision INTEGER NOT NULL CHECK (proposal_revision >= 1), schedule_change_log_id INTEGER NOT NULL, selected_decision_change_log_id INTEGER, generator_version INTEGER NOT NULL CHECK (generator_version >= 1), snapshot_codec_version INTEGER NOT NULL CHECK (snapshot_codec_version >= 1), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), amount_minor INTEGER, currency TEXT NOT NULL REFERENCES currencies(code), amount_state TEXT NOT NULL CHECK (amount_state IN ('known','estimated','missing')), PRIMARY KEY (generation_id, occurrence_id), FOREIGN KEY (generation_id, schedule_change_log_id) REFERENCES projection_entity_inputs(generation_id, change_log_id), FOREIGN KEY (generation_id, selected_decision_change_log_id) REFERENCES projection_entity_inputs(generation_id, change_log_id), CHECK ((amount_state='missing' AND amount_minor IS NULL) OR (amount_state IN ('known','estimated') AND amount_minor IS NOT NULL)) ) STRICT, WITHOUT ROWID;
CREATE TABLE projection_detail_inputs ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, instrument_id INTEGER NOT NULL, detail_revision INTEGER NOT NULL, PRIMARY KEY (generation_id, instrument_id, detail_revision), FOREIGN KEY (instrument_id, detail_revision) REFERENCES public_instrument_details(instrument_id, revision) ) STRICT, WITHOUT ROWID;
CREATE INDEX projection_detail_pin ON projection_detail_inputs(instrument_id, detail_revision);
CREATE TABLE category_postings ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, transaction_id TEXT NOT NULL REFERENCES transactions(id), part_key TEXT NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), category_id TEXT REFERENCES categories(id), date TEXT NOT NULL CHECK ((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date)), kind TEXT NOT NULL, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL REFERENCES currencies(code), recognition_policy TEXT NOT NULL, PRIMARY KEY (generation_id, transaction_id, part_key) ) STRICT, WITHOUT ROWID;
-- Exactly one unsplit parent OR its split parts, never both; writer/projection check.
CREATE INDEX category_posting_window ON category_postings(generation_id, category_id, date DESC, transaction_id DESC, part_key DESC);
CREATE INDEX category_posting_account ON category_postings(generation_id, account_id, date DESC, transaction_id DESC, part_key DESC);
CREATE TABLE summary_buckets ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, bucket_key TEXT NOT NULL, group_key TEXT NOT NULL, currency TEXT NOT NULL REFERENCES currencies(code), amount_minor INTEGER, value_state TEXT NOT NULL CHECK (value_state IN ('known','estimated','missing')), known_count INTEGER NOT NULL CHECK (known_count >= 0), missing_count INTEGER NOT NULL CHECK (missing_count >= 0), PRIMARY KEY (generation_id, bucket_key, group_key, currency), CHECK ((value_state = 'missing' AND amount_minor IS NULL) OR (value_state IN ('known','estimated') AND amount_minor IS NOT NULL)) ) STRICT, WITHOUT ROWID;
CREATE TABLE exact_series_points ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, point_ordinal INTEGER NOT NULL CHECK (point_ordinal >= 0), date TEXT NOT NULL CHECK (((length(date) = 10 AND date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date BETWEEN '0001-01-01' AND '9999-12-31' AND date(date, '+0 days') IS date))), same_day_order INTEGER NOT NULL CHECK (same_day_order >= 0), effective_at INTEGER CHECK (effective_at IS NULL OR effective_at >= 0), point_role TEXT NOT NULL CHECK (point_role IN ('observation','valuation','step','gap')), value_kind TEXT NOT NULL CHECK (value_kind IN ('money','decimal','missing')), value_state TEXT NOT NULL CHECK (value_state IN ('known','estimated','missing')), amount_minor INTEGER, value_decimal TEXT CHECK (value_decimal IS NULL OR (instr(value_decimal, char(0)) = 0 AND typeof(value_decimal) = 'text' AND length(value_decimal) BETWEEN 1 AND 78 AND value_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(value_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(value_decimal,2),'-') = 0 AND length(value_decimal) - length(replace(value_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(value_decimal,1,1) = '-' THEN substr(value_decimal,2) ELSE value_decimal END),1,1) BETWEEN '0' AND '9' AND substr(value_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(value_decimal,1,1) = '-' THEN substr(value_decimal,2) ELSE value_decimal END) NOT GLOB '0[0-9]*' AND value_decimal <> '-0' AND (instr(value_decimal,'.') = 0 OR (substr(value_decimal,-1) < '0' AND length(value_decimal) - instr(value_decimal,'.') <= 38)))), currency TEXT REFERENCES currencies(code), coverage_json TEXT NOT NULL CHECK (json_valid(coverage_json) AND length(CAST(coverage_json AS BLOB)) <= 4096), PRIMARY KEY (generation_id, point_ordinal), UNIQUE (generation_id, date, same_day_order), CHECK ((value_kind = 'money' AND amount_minor IS NOT NULL AND currency IS NOT NULL AND value_decimal IS NULL AND value_state <> 'missing') OR (value_kind = 'decimal' AND value_decimal IS NOT NULL AND amount_minor IS NULL AND value_state <> 'missing') OR (value_kind = 'missing' AND amount_minor IS NULL AND value_decimal IS NULL AND value_state = 'missing')), CHECK (point_role <> 'gap' OR value_kind = 'missing') ) STRICT, WITHOUT ROWID;
-- One sparse exact series per generation. Ordinals encode a resolved display order;
-- not an invented economic ordering. Historical reads never reread mutable source rows.
CREATE TABLE chart_buckets ( generation_id INTEGER NOT NULL REFERENCES projection_generations(id) ON DELETE CASCADE, first_point_ordinal INTEGER NOT NULL, low_point_ordinal INTEGER, high_point_ordinal INTEGER, last_point_ordinal INTEGER NOT NULL, representation TEXT NOT NULL DEFAULT 'envelope' CHECK (representation IN ('envelope','step','gap')), level INTEGER NOT NULL CHECK (level >= 0), bucket_index INTEGER NOT NULL CHECK (bucket_index >= 0), first_date TEXT NOT NULL CHECK (length(first_date) = 10 AND date(first_date, '+0 days') IS first_date), last_date TEXT NOT NULL CHECK (length(last_date) = 10 AND date(last_date, '+0 days') IS last_date), first_minor INTEGER, low_minor INTEGER, high_minor INTEGER, last_minor INTEGER, currency TEXT REFERENCES currencies(code), first_decimal TEXT CHECK (first_decimal IS NULL OR (instr(first_decimal, char(0)) = 0 AND typeof(first_decimal) = 'text' AND length(first_decimal) BETWEEN 1 AND 78 AND first_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(first_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(first_decimal,2),'-') = 0 AND length(first_decimal) - length(replace(first_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(first_decimal,1,1) = '-' THEN substr(first_decimal,2) ELSE first_decimal END),1,1) BETWEEN '0' AND '9' AND substr(first_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(first_decimal,1,1) = '-' THEN substr(first_decimal,2) ELSE first_decimal END) NOT GLOB '0[0-9]*' AND first_decimal <> '-0' AND (instr(first_decimal,'.') = 0 OR (substr(first_decimal,-1) < '0' AND length(first_decimal) - instr(first_decimal,'.') <= 38)))), low_decimal TEXT CHECK (low_decimal IS NULL OR (instr(low_decimal, char(0)) = 0 AND typeof(low_decimal) = 'text' AND length(low_decimal) BETWEEN 1 AND 78 AND low_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(low_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(low_decimal,2),'-') = 0 AND length(low_decimal) - length(replace(low_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(low_decimal,1,1) = '-' THEN substr(low_decimal,2) ELSE low_decimal END),1,1) BETWEEN '0' AND '9' AND substr(low_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(low_decimal,1,1) = '-' THEN substr(low_decimal,2) ELSE low_decimal END) NOT GLOB '0[0-9]*' AND low_decimal <> '-0' AND (instr(low_decimal,'.') = 0 OR (substr(low_decimal,-1) < '0' AND length(low_decimal) - instr(low_decimal,'.') <= 38)))), high_decimal TEXT CHECK (high_decimal IS NULL OR (instr(high_decimal, char(0)) = 0 AND typeof(high_decimal) = 'text' AND length(high_decimal) BETWEEN 1 AND 78 AND high_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(high_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(high_decimal,2),'-') = 0 AND length(high_decimal) - length(replace(high_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(high_decimal,1,1) = '-' THEN substr(high_decimal,2) ELSE high_decimal END),1,1) BETWEEN '0' AND '9' AND substr(high_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(high_decimal,1,1) = '-' THEN substr(high_decimal,2) ELSE high_decimal END) NOT GLOB '0[0-9]*' AND high_decimal <> '-0' AND (instr(high_decimal,'.') = 0 OR (substr(high_decimal,-1) < '0' AND length(high_decimal) - instr(high_decimal,'.') <= 38)))), last_decimal TEXT CHECK (last_decimal IS NULL OR (instr(last_decimal, char(0)) = 0 AND typeof(last_decimal) = 'text' AND length(last_decimal) BETWEEN 1 AND 78 AND last_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(last_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(last_decimal,2),'-') = 0 AND length(last_decimal) - length(replace(last_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(last_decimal,1,1) = '-' THEN substr(last_decimal,2) ELSE last_decimal END),1,1) BETWEEN '0' AND '9' AND substr(last_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(last_decimal,1,1) = '-' THEN substr(last_decimal,2) ELSE last_decimal END) NOT GLOB '0[0-9]*' AND last_decimal <> '-0' AND (instr(last_decimal,'.') = 0 OR (substr(last_decimal,-1) < '0' AND length(last_decimal) - instr(last_decimal,'.') <= 38)))), value_kind TEXT NOT NULL CHECK (value_kind IN ('money','decimal','missing')), source_count INTEGER NOT NULL CHECK (source_count >= 0), PRIMARY KEY (generation_id, level, bucket_index), FOREIGN KEY (generation_id, first_point_ordinal) REFERENCES exact_series_points(generation_id, point_ordinal), FOREIGN KEY (generation_id, low_point_ordinal) REFERENCES exact_series_points(generation_id, point_ordinal), FOREIGN KEY (generation_id, high_point_ordinal) REFERENCES exact_series_points(generation_id, point_ordinal), FOREIGN KEY (generation_id, last_point_ordinal) REFERENCES exact_series_points(generation_id, point_ordinal), CHECK (last_point_ordinal >= first_point_ordinal), CHECK ((representation = 'gap' AND value_kind = 'missing' AND low_point_ordinal IS NULL AND high_point_ordinal IS NULL) OR (representation <> 'gap' AND value_kind <> 'missing' AND low_point_ordinal IS NOT NULL AND high_point_ordinal IS NOT NULL AND low_point_ordinal BETWEEN first_point_ordinal AND last_point_ordinal AND high_point_ordinal BETWEEN first_point_ordinal AND last_point_ordinal)), CHECK (last_date >= first_date), CHECK ((value_kind = 'money' AND currency IS NOT NULL AND first_minor IS NOT NULL AND low_minor IS NOT NULL AND high_minor IS NOT NULL AND last_minor IS NOT NULL AND first_decimal IS NULL AND low_decimal IS NULL AND high_decimal IS NULL AND last_decimal IS NULL) OR (value_kind = 'decimal' AND currency IS NULL AND first_minor IS NULL AND low_minor IS NULL AND high_minor IS NULL AND last_minor IS NULL AND first_decimal IS NOT NULL AND low_decimal IS NOT NULL AND high_decimal IS NOT NULL AND last_decimal IS NOT NULL) OR (value_kind = 'missing' AND first_minor IS NULL AND low_minor IS NULL AND high_minor IS NULL AND last_minor IS NULL AND first_decimal IS NULL AND low_decimal IS NULL AND high_decimal IS NULL AND last_decimal IS NULL)) ) STRICT, WITHOUT ROWID;
-- Charts preserve extrema and source counts; exact drill-down resolves retained inputs.
-- Publication validates exact endpoint/extrema values/times, monotonic order and
-- gap separation. No known bucket may span an interior Missing point. Composite FKs
-- enforce generation membership, not the mathematical reduction rule.
CREATE TRIGGER exact_series_points_staging_insert BEFORE INSERT ON exact_series_points WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER exact_series_points_immutable_update BEFORE UPDATE ON exact_series_points BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER exact_series_points_retained_delete BEFORE DELETE ON exact_series_points WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TRIGGER chart_buckets_staging_insert BEFORE INSERT ON chart_buckets WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER chart_buckets_immutable_update BEFORE UPDATE ON chart_buckets BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER chart_buckets_retained_delete BEFORE DELETE ON chart_buckets WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TRIGGER lot_allocations_staging_insert BEFORE INSERT ON lot_allocations WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER lot_allocations_immutable_update BEFORE UPDATE ON lot_allocations BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER lot_allocations_retained_delete BEFORE DELETE ON lot_allocations WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TRIGGER projection_entity_inputs_staging_insert BEFORE INSERT ON projection_entity_inputs WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER projection_entity_inputs_immutable_update BEFORE UPDATE ON projection_entity_inputs BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER projection_entity_inputs_retained_delete BEFORE DELETE ON projection_entity_inputs WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TRIGGER projection_detail_inputs_staging_insert BEFORE INSERT ON projection_detail_inputs WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER projection_detail_inputs_immutable_update BEFORE UPDATE ON projection_detail_inputs BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER projection_detail_inputs_retained_delete BEFORE DELETE ON projection_detail_inputs WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TRIGGER projection_inputs_staging_insert BEFORE INSERT ON projection_inputs WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER projection_inputs_immutable_update BEFORE UPDATE ON projection_inputs BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER projection_inputs_retained_delete BEFORE DELETE ON projection_inputs WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TRIGGER projection_quote_inputs_staging_insert BEFORE INSERT ON projection_quote_inputs WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER projection_quote_inputs_immutable_update BEFORE UPDATE ON projection_quote_inputs BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
