CREATE TRIGGER summary_buckets_immutable_update BEFORE UPDATE ON summary_buckets BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER summary_buckets_retained_delete BEFORE DELETE ON summary_buckets WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TRIGGER category_postings_staging_insert BEFORE INSERT ON category_postings WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER category_postings_immutable_update BEFORE UPDATE ON category_postings BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER category_postings_retained_delete BEFORE DELETE ON category_postings WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TABLE local_jobs ( id TEXT PRIMARY KEY NOT NULL, kind TEXT NOT NULL, db_epoch TEXT NOT NULL, priority INTEGER NOT NULL CHECK (priority BETWEEN 0 AND 4), state TEXT NOT NULL CHECK (state IN ('queued','running','paused','complete','failed','cancelled')), lease_owner TEXT, lease_until INTEGER, generation_id INTEGER REFERENCES projection_generations(id), progress_count INTEGER NOT NULL DEFAULT 0 CHECK (progress_count >= 0), safe_error_code TEXT, CHECK ((lease_owner IS NULL) = (lease_until IS NULL)) ) STRICT, WITHOUT ROWID;
-- Temporary source bytes are encrypted private staging, not retained receipts.
-- Recovery omits these bytes by policy; restored incomplete imports become sourceNeeded.
CREATE TABLE import_parse_configs ( id TEXT PRIMARY KEY NOT NULL, parser_id TEXT NOT NULL, parser_version INTEGER NOT NULL CHECK (parser_version >= 1), identity_version INTEGER NOT NULL CHECK (identity_version >= 1), config_version INTEGER NOT NULL CHECK (config_version >= 1), config_json TEXT NOT NULL CHECK (json_valid(config_json) AND length(CAST(config_json AS BLOB)) <= 262144), content_digest BLOB NOT NULL CHECK (length(content_digest) = 32) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER parse_config_immutable BEFORE UPDATE ON import_parse_configs BEGIN SELECT RAISE(ABORT, 'immutable_parse_configuration'); END;
CREATE TABLE import_sources ( id TEXT PRIMARY KEY NOT NULL, object_name TEXT NOT NULL UNIQUE CHECK (length(CAST(object_name AS BLOB)) BETWEEN 16 AND 128 AND instr(object_name,char(0)) = 0 AND object_name NOT GLOB '*[^a-zA-Z0-9_-]*'), file_digest BLOB NOT NULL CHECK (length(file_digest) = 32), byte_count INTEGER NOT NULL CHECK (byte_count >= 0), staging_key_reference TEXT NOT NULL, install_epoch TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('available','released','missing')) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER import_source_identity BEFORE UPDATE ON import_sources WHEN NEW.id IS NOT OLD.id OR NEW.object_name IS NOT OLD.object_name OR NEW.file_digest IS NOT OLD.file_digest OR NEW.byte_count IS NOT OLD.byte_count OR NEW.staging_key_reference IS NOT OLD.staging_key_reference OR NEW.install_epoch IS NOT OLD.install_epoch BEGIN SELECT RAISE(ABORT, 'immutable_import_source_identity'); END;
CREATE TABLE import_job_inputs ( job_id TEXT PRIMARY KEY NOT NULL REFERENCES local_jobs(id), batch_id TEXT NOT NULL REFERENCES import_batches(id), source_id TEXT NOT NULL REFERENCES import_sources(id), parse_config_id TEXT NOT NULL REFERENCES import_parse_configs(id) ) STRICT, WITHOUT ROWID;
CREATE INDEX import_job_batch ON import_job_inputs(batch_id, job_id);
CREATE INDEX import_job_source ON import_job_inputs(source_id);
CREATE INDEX import_job_config ON import_job_inputs(parse_config_id);
CREATE TRIGGER import_job_input_immutable BEFORE UPDATE ON import_job_inputs BEGIN SELECT RAISE(ABORT, 'immutable_import_job_input'); END;
-- The shared native lifecycle registry leases staged files before creation. A job
-- may resume only with matching source digest, configuration and supported parser.
CREATE TABLE month_closes ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(CAST(id AS BLOB)) = 36 AND instr(id,char(0)) = 0 AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND substr(id,15,1) = '7' AND substr(id,20,1) IN ('8','9','a','b') AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' ), entity_kind TEXT GENERATED ALWAYS AS ('month_closes') VIRTUAL, created_at INTEGER NOT NULL CHECK (created_at >= 0), updated_at INTEGER NOT NULL CHECK (updated_at >= 0), deleted_at INTEGER CHECK (deleted_at IS NULL OR deleted_at >= 0), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), month TEXT NOT NULL UNIQUE CHECK (length(month) = 7 AND month GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]' AND substr(month,6,2) BETWEEN '01' AND '12'), started_at INTEGER NOT NULL CHECK (started_at >= 0), steps_json TEXT NOT NULL CHECK (json_valid(steps_json))) STRICT;
CREATE TRIGGER month_closes_identity AFTER INSERT ON month_closes BEGIN INSERT INTO entity_registry(id, entity_kind) VALUES (NEW.id, 'month_closes'); END;
CREATE TRIGGER month_closes_revision BEFORE UPDATE ON month_closes WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.revision < OLD.revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_entity_revision'); END;
CREATE TRIGGER month_closes_retain BEFORE DELETE ON month_closes BEGIN SELECT RAISE(ABORT, 'authored_record_requires_soft_delete'); END;
CREATE TABLE close_revisions ( id TEXT PRIMARY KEY NOT NULL, close_id TEXT NOT NULL REFERENCES month_closes(id), sequence INTEGER NOT NULL CHECK (sequence >= 1), previous_revision_id TEXT, cutoff_date TEXT NOT NULL CHECK ((length(cutoff_date) = 10 AND cutoff_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND cutoff_date BETWEEN '0001-01-01' AND '9999-12-31' AND date(cutoff_date, '+0 days') IS cutoff_date)), saved_at INTEGER NOT NULL CHECK (saved_at >= 0), source_commit_sequence INTEGER NOT NULL CHECK (source_commit_sequence >= 0), method_version INTEGER NOT NULL CHECK (method_version >= 1), operation_id TEXT NOT NULL REFERENCES operation_receipts(operation_id) DEFERRABLE INITIALLY DEFERRED, currency TEXT NOT NULL REFERENCES currencies(code), total_assets_minor INTEGER, total_liabilities_minor INTEGER, value_state TEXT NOT NULL CHECK (value_state IN ('known','estimated','missing')), coverage_json TEXT NOT NULL CHECK (json_valid(coverage_json)), result_json TEXT NOT NULL CHECK (json_valid(result_json)), UNIQUE (close_id, sequence), UNIQUE (close_id, id), FOREIGN KEY (close_id, previous_revision_id) REFERENCES close_revisions(close_id, id), CHECK ((sequence = 1 AND previous_revision_id IS NULL) OR (sequence > 1 AND previous_revision_id IS NOT NULL)), CHECK (previous_revision_id IS NULL OR previous_revision_id <> id), CHECK ((value_state = 'missing' AND total_assets_minor IS NULL AND total_liabilities_minor IS NULL) OR (value_state IN ('known','estimated') AND total_assets_minor IS NOT NULL AND total_liabilities_minor IS NOT NULL)) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER close_revisions_immutable_update BEFORE UPDATE ON close_revisions BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER close_revisions_immutable_delete BEFORE DELETE ON close_revisions BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
-- Saved close stores exact results AND immutable input versions, never cache-only IDs.
CREATE TABLE close_quote_inputs ( close_revision_id TEXT NOT NULL REFERENCES close_revisions(id), quote_id INTEGER NOT NULL REFERENCES price_quotes(id), PRIMARY KEY (close_revision_id, quote_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX close_quote_pin ON close_quote_inputs(quote_id);
CREATE TRIGGER close_quote_inputs_immutable_update BEFORE UPDATE ON close_quote_inputs BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER close_quote_inputs_immutable_delete BEFORE DELETE ON close_quote_inputs BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
CREATE TABLE close_entity_inputs ( close_revision_id TEXT NOT NULL REFERENCES close_revisions(id), change_log_id INTEGER NOT NULL REFERENCES change_log(id), PRIMARY KEY (close_revision_id, change_log_id) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER close_entity_inputs_immutable_update BEFORE UPDATE ON close_entity_inputs BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER close_entity_inputs_immutable_delete BEFORE DELETE ON close_entity_inputs BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
CREATE TABLE close_detail_inputs ( close_revision_id TEXT NOT NULL REFERENCES close_revisions(id), instrument_id INTEGER NOT NULL, detail_revision INTEGER NOT NULL, PRIMARY KEY (close_revision_id, instrument_id, detail_revision), FOREIGN KEY (instrument_id, detail_revision) REFERENCES public_instrument_details(instrument_id, revision) ) STRICT, WITHOUT ROWID;
CREATE INDEX close_detail_pin ON close_detail_inputs(instrument_id, detail_revision);
CREATE TRIGGER close_detail_inputs_immutable_update BEFORE UPDATE ON close_detail_inputs BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER close_detail_inputs_immutable_delete BEFORE DELETE ON close_detail_inputs BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
CREATE TABLE close_attachments ( close_revision_id TEXT NOT NULL REFERENCES close_revisions(id), attachment_id TEXT NOT NULL REFERENCES attachment_manifests(id), PRIMARY KEY (close_revision_id, attachment_id) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER close_attachments_immutable_update BEFORE UPDATE ON close_attachments BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER close_attachments_immutable_delete BEFORE DELETE ON close_attachments BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
CREATE TABLE close_lot_allocations ( close_revision_id TEXT NOT NULL REFERENCES close_revisions(id), disposal_event_id TEXT NOT NULL REFERENCES investment_transactions(id), lot_id TEXT NOT NULL REFERENCES lots(id), quantity_decimal TEXT NOT NULL CHECK (instr(quantity_decimal, char(0)) = 0 AND typeof(quantity_decimal) = 'text' AND length(quantity_decimal) BETWEEN 1 AND 78 AND quantity_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(quantity_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(quantity_decimal,2),'-') = 0 AND length(quantity_decimal) - length(replace(quantity_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END),1,1) BETWEEN '0' AND '9' AND substr(quantity_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(quantity_decimal,1,1) = '-' THEN substr(quantity_decimal,2) ELSE quantity_decimal END) NOT GLOB '0[0-9]*' AND quantity_decimal <> '-0' AND (instr(quantity_decimal,'.') = 0 OR (substr(quantity_decimal,-1) < '0' AND length(quantity_decimal) - instr(quantity_decimal,'.') <= 38)) AND substr(quantity_decimal,1,1) <> '-' AND quantity_decimal <> '0'), cost_minor INTEGER, currency TEXT NOT NULL REFERENCES currencies(code), cost_state TEXT NOT NULL CHECK (cost_state IN ('known','missing')), method_version INTEGER NOT NULL CHECK (method_version >= 1), PRIMARY KEY (close_revision_id, disposal_event_id, lot_id), CHECK ((cost_state = 'missing' AND cost_minor IS NULL) OR (cost_state = 'known' AND cost_minor IS NOT NULL)) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER close_lot_allocations_immutable_update BEFORE UPDATE ON close_lot_allocations BEGIN SELECT RAISE(ABORT, 'immutable_history'); END;
CREATE TRIGGER close_lot_allocations_immutable_delete BEFORE DELETE ON close_lot_allocations BEGIN SELECT RAISE(ABORT, 'retained_history'); END;
-- Search copies live, parsed fields only, inside SQLCipher. Single writer updates the
-- document with its source command; triggers synchronize the external-content FTS index.
CREATE TABLE search_documents ( id INTEGER PRIMARY KEY, transaction_id TEXT REFERENCES transactions(id), account_id TEXT REFERENCES accounts(id), merchant TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', account_name TEXT NOT NULL DEFAULT '', CHECK ((transaction_id IS NOT NULL) + (account_id IS NOT NULL) = 1) ) STRICT;
CREATE UNIQUE INDEX search_transaction ON search_documents(transaction_id) WHERE transaction_id IS NOT NULL;
CREATE UNIQUE INDEX search_account ON search_documents(account_id) WHERE account_id IS NOT NULL;
CREATE VIRTUAL TABLE search_fts USING fts5( merchant, note, account_name, content='search_documents', content_rowid='id', tokenize='unicode61 remove_diacritics 2' );
CREATE TRIGGER search_insert AFTER INSERT ON search_documents BEGIN INSERT INTO search_fts(rowid, merchant, note, account_name) VALUES (NEW.id, NEW.merchant, NEW.note, NEW.account_name); END;
CREATE TRIGGER search_delete AFTER DELETE ON search_documents BEGIN INSERT INTO search_fts(search_fts, rowid, merchant, note, account_name) VALUES ('delete', OLD.id, OLD.merchant, OLD.note, OLD.account_name); END;
CREATE TRIGGER search_update AFTER UPDATE ON search_documents BEGIN INSERT INTO search_fts(search_fts, rowid, merchant, note, account_name) VALUES ('delete', OLD.id, OLD.merchant, OLD.note, OLD.account_name); INSERT INTO search_fts(rowid, merchant, note, account_name) VALUES (NEW.id, NEW.merchant, NEW.note, NEW.account_name); END;
-- Additional writer invariants (must have independent acceptance tests):
-- * ownership percent is within 0..100 using exact Decimal comparison;
-- * every authored mutation has matching immutable ChangeLog + receipt + invalidation;
-- * receipt/state/commit sequence agree; receipt only describes one complete command;
-- * registry kind has an existing subtype; entity and expected revisions match;
-- * no live semantic link targets a soft-deleted account/event/lot/obligation;
-- * transfer/split/acquisition/settlement/reinvestment source graphs reconcile exactly;
-- * automatic lot allocations/gains/checkpoints publish as one coherent derived generation;
-- * corrected evidence points to same account/security/pair and forms an acyclic chain;
-- * current anchor/quote/projection pointers meet as-of, basis, revision and live rules;
-- * source claim, Inbox decision and accepted event links resolve as one atomic outcome;
-- * submitted draft payload cannot change until its prior operation outcome resolves;
-- * close input set is complete, prior sequence adjacent and cutoff/coverage explicit;
-- * published generations never mutate their inputs/output; replacement gets new ID;
-- * quote/file/key eviction checks ALL active/staged/retained generation references.
-- Foreign key child indexes beyond hot paths are selected after measured query plans.
-- Later SPEC modules (goals/policies/tax/budgets/grants/settings/parser templates)
-- require separate reviewed schema migrations; do not infer them from generic JSON.
-- DB-002: shared metrics, durable history pins, public assets and layouts.
CREATE TRIGGER read_revision_monotonic BEFORE UPDATE OF read_revision ON db_state WHEN NEW.read_revision < OLD.read_revision OR NEW.read_revision > OLD.read_revision + 1 BEGIN SELECT RAISE(ABORT, 'invalid_read_revision'); END;
-- One admitted calculation for a canonical key. A superseded job must retire its
-- staging generation before the next job starts; different screens join that job.
CREATE TABLE metric_values ( generation_id INTEGER PRIMARY KEY REFERENCES projection_generations(id) ON DELETE CASCADE, value_kind TEXT NOT NULL CHECK (value_kind IN ('money','decimal','count')), value_state TEXT NOT NULL CHECK (value_state IN ('known','estimated','missing','noneRecorded','notAvailable')), value_basis TEXT NOT NULL DEFAULT 'actual' CHECK (value_basis IN ('actual','expected')), amount_minor INTEGER, value_decimal TEXT CHECK (value_decimal IS NULL OR (instr(value_decimal, char(0)) = 0 AND typeof(value_decimal) = 'text' AND length(value_decimal) BETWEEN 1 AND 78 AND value_decimal NOT GLOB '*[^0-9.-]*' AND length(replace(replace(value_decimal,'-',''),'.','')) BETWEEN 1 AND 76 AND instr(substr(value_decimal,2),'-') = 0 AND length(value_decimal) - length(replace(value_decimal,'.','')) <= 1 AND substr((CASE WHEN substr(value_decimal,1,1) = '-' THEN substr(value_decimal,2) ELSE value_decimal END),1,1) BETWEEN '0' AND '9' AND substr(value_decimal,-1) BETWEEN '0' AND '9' AND (CASE WHEN substr(value_decimal,1,1) = '-' THEN substr(value_decimal,2) ELSE value_decimal END) NOT GLOB '0[0-9]*' AND value_decimal <> '-0' AND (instr(value_decimal,'.') = 0 OR (substr(value_decimal,-1) < '0' AND length(value_decimal) - instr(value_decimal,'.') <= 38)))), count_value INTEGER CHECK (count_value IS NULL OR count_value >= 0), reason_code TEXT CHECK (reason_code IS NULL OR reason_code IN ('insufficientInputs','undefinedResult','unsupportedOrder','noRecords')), CHECK ((value_state IN ('known','estimated') AND reason_code IS NULL AND ((value_kind = 'money' AND amount_minor IS NOT NULL AND value_decimal IS NULL AND count_value IS NULL) OR (value_kind = 'decimal' AND amount_minor IS NULL AND value_decimal IS NOT NULL AND count_value IS NULL) OR (value_kind = 'count' AND amount_minor IS NULL AND value_decimal IS NULL AND count_value IS NOT NULL))) OR (value_state IN ('missing','noneRecorded','notAvailable') AND amount_minor IS NULL AND value_decimal IS NULL AND count_value IS NULL AND reason_code IS NOT NULL)) ) STRICT;
-- Currency and method come from the key. The bundled metric registry owns the
-- exact unit, formula, allowed basis and dependency recipe; no executable DB formulas.
CREATE TRIGGER metric_values_staging_insert BEFORE INSERT ON metric_values WHEN (SELECT status FROM projection_generations WHERE id=NEW.generation_id) <> 'staging' BEGIN SELECT RAISE(ABORT, 'generation_requires_staging'); END;
CREATE TRIGGER metric_values_immutable_update BEFORE UPDATE ON metric_values BEGIN SELECT RAISE(ABORT, 'immutable_generation_row'); END;
CREATE TRIGGER metric_values_retained_delete BEFORE DELETE ON metric_values WHEN (SELECT status FROM projection_generations WHERE id=OLD.generation_id) IN ('published','obsolete') BEGIN SELECT RAISE(ABORT, 'retained_generation_row'); END;
CREATE TRIGGER current_projection_valid_insert BEFORE INSERT ON current_projections WHEN NOT EXISTS ( SELECT 1 FROM projection_generations g JOIN db_state s ON s.singleton = 1 WHERE g.id = NEW.generation_id AND g.key_id = NEW.key_id AND g.status = 'published' AND g.db_epoch = s.db_epoch AND NOT EXISTS (SELECT 1 FROM projection_inputs i LEFT JOIN dependency_revisions d ON d.scope_id = i.scope_id WHERE i.generation_id = g.id AND (d.revision IS NULL OR d.revision <> i.input_revision)) ) BEGIN SELECT RAISE(ABORT, 'invalid_projection_publication'); END;
CREATE TRIGGER current_projection_valid_update BEFORE UPDATE ON current_projections WHEN NEW.key_id <> OLD.key_id OR NOT EXISTS ( SELECT 1 FROM projection_generations g JOIN db_state s ON s.singleton = 1 WHERE g.id = NEW.generation_id AND g.key_id = NEW.key_id AND g.status = 'published' AND g.db_epoch = s.db_epoch AND NOT EXISTS (SELECT 1 FROM projection_inputs i LEFT JOIN dependency_revisions d ON d.scope_id = i.scope_id WHERE i.generation_id = g.id AND (d.revision IS NULL OR d.revision <> i.input_revision)) ) BEGIN SELECT RAISE(ABORT, 'invalid_projection_publication'); END;
-- Retained historical observations share the original row, not copied prices or
-- details. These pins outlive every disposable projection and current pointer.
CREATE TABLE history_quote_pins ( quote_id INTEGER PRIMARY KEY REFERENCES price_quotes(id), retained_at INTEGER NOT NULL CHECK (retained_at >= 0) ) STRICT;
CREATE TABLE history_detail_pins ( instrument_id INTEGER NOT NULL, detail_revision INTEGER NOT NULL, retained_at INTEGER NOT NULL CHECK (retained_at >= 0), PRIMARY KEY (instrument_id, detail_revision), FOREIGN KEY (instrument_id, detail_revision) REFERENCES public_instrument_details(instrument_id, revision) ) STRICT, WITHOUT ROWID;
CREATE TRIGGER history_quote_pins_immutable BEFORE UPDATE ON history_quote_pins BEGIN SELECT RAISE(ABORT, 'immutable_history_pin'); END;
CREATE TRIGGER history_quote_pins_retained BEFORE DELETE ON history_quote_pins BEGIN SELECT RAISE(ABORT, 'retained_history_pin'); END;
CREATE TRIGGER history_detail_pins_immutable BEFORE UPDATE ON history_detail_pins BEGIN SELECT RAISE(ABORT, 'immutable_history_pin'); END;
CREATE TRIGGER history_detail_pins_retained BEFORE DELETE ON history_detail_pins BEGIN SELECT RAISE(ABORT, 'retained_history_pin'); END;
-- Metadata stays in the vault. Bytes use the existing authenticated file store.
-- One provider asset/rendition maps to one file; many references can share it.
CREATE TABLE public_asset_cache ( provider_id INTEGER NOT NULL REFERENCES market_providers(id), asset_key TEXT NOT NULL CHECK (length(CAST(asset_key AS BLOB)) BETWEEN 1 AND 192 AND instr(asset_key,char(0)) = 0 AND instr(asset_key,'://') = 0), rendition TEXT NOT NULL CHECK (rendition IN ('logo-64','logo-128','logo-256')), attachment_id TEXT NOT NULL REFERENCES attachment_manifests(id), validated_at INTEGER NOT NULL CHECK (validated_at >= 0), PRIMARY KEY (provider_id, asset_key, rendition) ) STRICT, WITHOUT ROWID;
CREATE INDEX public_asset_file_reference ON public_asset_cache(attachment_id);
CREATE INDEX attachment_digest_lookup ON attachment_manifests(authenticated_digest, plaintext_size, media_type);
CREATE TRIGGER public_asset_bounded_insert BEFORE INSERT ON public_asset_cache WHEN NOT EXISTS (SELECT 1 FROM attachment_manifests a WHERE a.id = NEW.attachment_id AND a.media_type IN ('image/png','image/jpeg','image/webp') AND a.plaintext_size BETWEEN 1 AND 1048576) BEGIN SELECT RAISE(ABORT, 'invalid_public_asset'); END;
CREATE TRIGGER public_asset_bounded_update BEFORE UPDATE ON public_asset_cache WHEN NOT EXISTS (SELECT 1 FROM attachment_manifests a WHERE a.id = NEW.attachment_id AND a.media_type IN ('image/png','image/jpeg','image/webp') AND a.plaintext_size BETWEEN 1 AND 1048576) BEGIN SELECT RAISE(ABORT, 'invalid_public_asset'); END;
CREATE TABLE layout_surfaces ( surface_key TEXT PRIMARY KEY NOT NULL CHECK (surface_key IN ('screen:home','screen:spending','screen:moneyIn','screen:wealth','screen:investments','screen:calendar','screen:goals','screen:protect','screen:tax','tiles:quickLook')), catalogue_version INTEGER NOT NULL CHECK (catalogue_version >= 1), base_layout_version INTEGER NOT NULL CHECK (base_layout_version >= 1), updated_at INTEGER NOT NULL CHECK (updated_at >= 0) ) STRICT;
-- WIDGETS-007: section keys come from the bundled default layout file, never user
-- text. 'untitled' is the reserved section of every surface and the only tile section;
-- its case variants are rejected.
-- Item positions are consecutive from zero within each section (writer rule).
CREATE TABLE layout_sections ( surface_key TEXT NOT NULL REFERENCES layout_surfaces(surface_key) ON DELETE CASCADE, position INTEGER NOT NULL CHECK (position >= 0), section_key TEXT NOT NULL CHECK (length(section_key) BETWEEN 1 AND 64 AND instr(section_key,char(0)) = 0 AND section_key NOT GLOB '*[^A-Za-z0-9._-]*' AND (section_key = 'untitled' OR lower(section_key) < 'untitled')), PRIMARY KEY (surface_key, position), UNIQUE (surface_key, section_key), CHECK (surface_key <> 'tiles:quickLook' OR section_key = 'untitled') ) STRICT, WITHOUT ROWID;
CREATE TABLE layout_items ( surface_key TEXT NOT NULL, section_key TEXT NOT NULL, position INTEGER NOT NULL CHECK (position >= 0), item_key TEXT NOT NULL CHECK (length(item_key) BETWEEN 1 AND 64 AND instr(item_key,char(0)) = 0), size TEXT NOT NULL CHECK (size IN ('full','half')), PRIMARY KEY (surface_key, section_key, position), UNIQUE (surface_key, item_key), FOREIGN KEY (surface_key, section_key) REFERENCES layout_sections(surface_key, section_key) ON DELETE CASCADE, CHECK (surface_key <> 'tiles:quickLook' OR size = 'full') ) STRICT, WITHOUT ROWID;
-- DB4-10: REPLACE would delete a conflicting parent row and cascade its
-- children. The writer deletes, then inserts; a conflicting write aborts.
CREATE TRIGGER layout_surfaces_no_replace BEFORE INSERT ON layout_surfaces WHEN EXISTS (SELECT 1 FROM layout_surfaces WHERE surface_key = NEW.surface_key) BEGIN SELECT RAISE(ABORT, 'layout_row_exists'); END;
CREATE TRIGGER layout_surfaces_no_replace_update BEFORE UPDATE OF surface_key ON layout_surfaces WHEN NEW.surface_key <> OLD.surface_key AND EXISTS (SELECT 1 FROM layout_surfaces WHERE surface_key = NEW.surface_key) BEGIN SELECT RAISE(ABORT, 'layout_row_exists'); END;
CREATE TRIGGER layout_sections_no_replace BEFORE INSERT ON layout_sections WHEN EXISTS (SELECT 1 FROM layout_sections WHERE surface_key = NEW.surface_key AND (position = NEW.position OR section_key = NEW.section_key)) BEGIN SELECT RAISE(ABORT, 'layout_row_exists'); END;
CREATE TRIGGER layout_sections_no_replace_update BEFORE UPDATE OF surface_key, position, section_key ON layout_sections WHEN EXISTS (SELECT 1 FROM layout_sections WHERE surface_key = NEW.surface_key AND NOT (surface_key = OLD.surface_key AND position = OLD.position) AND (position = NEW.position OR section_key = NEW.section_key)) BEGIN SELECT RAISE(ABORT, 'layout_row_exists'); END;
CREATE TRIGGER layout_items_no_replace BEFORE INSERT ON layout_items WHEN EXISTS (SELECT 1 FROM layout_items WHERE surface_key = NEW.surface_key AND ((section_key = NEW.section_key AND position = NEW.position) OR item_key = NEW.item_key)) BEGIN SELECT RAISE(ABORT, 'layout_row_exists'); END;
CREATE TRIGGER layout_items_no_replace_update BEFORE UPDATE OF surface_key, section_key, position, item_key ON layout_items WHEN EXISTS (SELECT 1 FROM layout_items WHERE surface_key = NEW.surface_key AND NOT (surface_key = OLD.surface_key AND section_key = OLD.section_key AND position = OLD.position) AND ((section_key = NEW.section_key AND position = NEW.position) OR item_key = NEW.item_key)) BEGIN SELECT RAISE(ABORT, 'layout_row_exists'); END;
-- ARCH-REVIEW-002 reference version 3 guards and cleanup indexes.
-- Dependency identity/revision pairs survive all ordinary cache cleanup.
CREATE TRIGGER dependency_revision_retain BEFORE DELETE ON dependency_revisions BEGIN SELECT RAISE(ABORT, 'retained_dependency_revision'); END;
-- REPLACE can bypass delete triggers when recursive_triggers is off. Explicit
-- UPDATE is the only supported revision change, guarded by dependency_monotonic.
CREATE TRIGGER dependency_revision_insert BEFORE INSERT ON dependency_revisions WHEN EXISTS (SELECT 1 FROM dependency_revisions WHERE scope_id = NEW.scope_id) BEGIN SELECT RAISE(ABORT, 'existing_dependency_revision'); END;
CREATE INDEX local_jobs_generation ON local_jobs(generation_id);
CREATE INDEX event_attachment_reverse ON event_attachments(attachment_id);
CREATE INDEX draft_attachment_reverse ON draft_attachments(attachment_id);
CREATE INDEX close_attachment_reverse ON close_attachments(attachment_id);
ALTER TABLE db_state ADD COLUMN inbox_revision INTEGER NOT NULL DEFAULT 0 CHECK (inbox_revision >= 0);
ALTER TABLE import_batches ADD COLUMN inbox_published INTEGER NOT NULL DEFAULT 0 CHECK (inbox_published IN (0,1));
-- ARCH-REVIEW-003: protected identities reject replacement through every unique key.
-- Use owner lookup then explicit INSERT/UPDATE; no OR REPLACE/IGNORE/upsert on
-- protected tables. Integer IDs are allocated as positive values by the owner.
CREATE TRIGGER guard_accounts_insert BEFORE INSERT ON "accounts" WHEN EXISTS (SELECT 1 FROM "accounts" AS q WHERE (q."id"=NEW."id") OR (q."id"=NEW."id" AND q."currency"=NEW."currency")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_accounts_update BEFORE UPDATE ON "accounts" WHEN NEW."id" IS NOT OLD."id" OR EXISTS (SELECT 1 FROM "accounts" AS q WHERE ((q."id"=NEW."id") OR (q."id"=NEW."id" AND q."currency"=NEW."currency")) AND NOT (q."id" IS OLD."id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_attachment_manifests_insert BEFORE INSERT ON "attachment_manifests" WHEN EXISTS (SELECT 1 FROM "attachment_manifests" AS q WHERE (q."id"=NEW."id") OR (q."object_name"=NEW."object_name")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_attachment_manifests_update BEFORE UPDATE ON "attachment_manifests" WHEN NEW."id" IS NOT OLD."id" OR EXISTS (SELECT 1 FROM "attachment_manifests" AS q WHERE ((q."id"=NEW."id") OR (q."object_name"=NEW."object_name")) AND NOT (q."id" IS OLD."id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_balance_anchors_insert BEFORE INSERT ON "balance_anchors" WHEN EXISTS (SELECT 1 FROM "balance_anchors" AS q WHERE (q."id"=NEW."id") OR (q."account_id"=NEW."account_id" AND q."id"=NEW."id")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_balance_anchors_update BEFORE UPDATE ON "balance_anchors" WHEN NEW."id" IS NOT OLD."id" OR EXISTS (SELECT 1 FROM "balance_anchors" AS q WHERE ((q."id"=NEW."id") OR (q."account_id"=NEW."account_id" AND q."id"=NEW."id")) AND NOT (q."id" IS OLD."id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_card_statement_obligations_insert BEFORE INSERT ON "card_statement_obligations" WHEN EXISTS (SELECT 1 FROM "card_statement_obligations" AS q WHERE (q."id"=NEW."id") OR (q."statement_id"=NEW."statement_id")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_card_statement_obligations_update BEFORE UPDATE ON "card_statement_obligations" WHEN NEW."id" IS NOT OLD."id" OR EXISTS (SELECT 1 FROM "card_statement_obligations" AS q WHERE ((q."id"=NEW."id") OR (q."statement_id"=NEW."statement_id")) AND NOT (q."id" IS OLD."id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_card_statements_insert BEFORE INSERT ON "card_statements" WHEN EXISTS (SELECT 1 FROM "card_statements" AS q WHERE (q."id"=NEW."id")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_card_statements_update BEFORE UPDATE ON "card_statements" WHEN NEW."id" IS NOT OLD."id" OR EXISTS (SELECT 1 FROM "card_statements" AS q WHERE ((q."id"=NEW."id")) AND NOT (q."id" IS OLD."id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_categories_insert BEFORE INSERT ON "categories" WHEN EXISTS (SELECT 1 FROM "categories" AS q WHERE (q."id"=NEW."id")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_categories_update BEFORE UPDATE ON "categories" WHEN NEW."id" IS NOT OLD."id" OR EXISTS (SELECT 1 FROM "categories" AS q WHERE ((q."id"=NEW."id")) AND NOT (q."id" IS OLD."id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_category_postings_insert BEFORE INSERT ON "category_postings" WHEN EXISTS (SELECT 1 FROM "category_postings" AS q WHERE (q."generation_id"=NEW."generation_id" AND q."transaction_id"=NEW."transaction_id" AND q."part_key"=NEW."part_key")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_category_postings_update BEFORE UPDATE ON "category_postings" WHEN NEW."generation_id" IS NOT OLD."generation_id" OR NEW."transaction_id" IS NOT OLD."transaction_id" OR NEW."part_key" IS NOT OLD."part_key" OR EXISTS (SELECT 1 FROM "category_postings" AS q WHERE ((q."generation_id"=NEW."generation_id" AND q."transaction_id"=NEW."transaction_id" AND q."part_key"=NEW."part_key")) AND NOT (q."generation_id" IS OLD."generation_id" AND q."transaction_id" IS OLD."transaction_id" AND q."part_key" IS OLD."part_key")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_change_log_insert BEFORE INSERT ON "change_log" WHEN EXISTS (SELECT 1 FROM "change_log" AS q WHERE (q."id"=NEW."id") OR (q."operation_id"=NEW."operation_id" AND q."ordinal"=NEW."ordinal")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_change_log_update BEFORE UPDATE ON "change_log" WHEN NEW."id" IS NOT OLD."id" OR EXISTS (SELECT 1 FROM "change_log" AS q WHERE ((q."id"=NEW."id") OR (q."operation_id"=NEW."operation_id" AND q."ordinal"=NEW."ordinal")) AND NOT (q."id" IS OLD."id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_chart_buckets_insert BEFORE INSERT ON "chart_buckets" WHEN EXISTS (SELECT 1 FROM "chart_buckets" AS q WHERE (q."generation_id"=NEW."generation_id" AND q."level"=NEW."level" AND q."bucket_index"=NEW."bucket_index")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_chart_buckets_update BEFORE UPDATE ON "chart_buckets" WHEN NEW."generation_id" IS NOT OLD."generation_id" OR NEW."level" IS NOT OLD."level" OR NEW."bucket_index" IS NOT OLD."bucket_index" OR EXISTS (SELECT 1 FROM "chart_buckets" AS q WHERE ((q."generation_id"=NEW."generation_id" AND q."level"=NEW."level" AND q."bucket_index"=NEW."bucket_index")) AND NOT (q."generation_id" IS OLD."generation_id" AND q."level" IS OLD."level" AND q."bucket_index" IS OLD."bucket_index")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_close_attachments_insert BEFORE INSERT ON "close_attachments" WHEN EXISTS (SELECT 1 FROM "close_attachments" AS q WHERE (q."close_revision_id"=NEW."close_revision_id" AND q."attachment_id"=NEW."attachment_id")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_close_attachments_update BEFORE UPDATE ON "close_attachments" WHEN NEW."close_revision_id" IS NOT OLD."close_revision_id" OR NEW."attachment_id" IS NOT OLD."attachment_id" OR EXISTS (SELECT 1 FROM "close_attachments" AS q WHERE ((q."close_revision_id"=NEW."close_revision_id" AND q."attachment_id"=NEW."attachment_id")) AND NOT (q."close_revision_id" IS OLD."close_revision_id" AND q."attachment_id" IS OLD."attachment_id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_close_detail_inputs_insert BEFORE INSERT ON "close_detail_inputs" WHEN EXISTS (SELECT 1 FROM "close_detail_inputs" AS q WHERE (q."close_revision_id"=NEW."close_revision_id" AND q."instrument_id"=NEW."instrument_id" AND q."detail_revision"=NEW."detail_revision")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_close_detail_inputs_update BEFORE UPDATE ON "close_detail_inputs" WHEN NEW."close_revision_id" IS NOT OLD."close_revision_id" OR NEW."instrument_id" IS NOT OLD."instrument_id" OR NEW."detail_revision" IS NOT OLD."detail_revision" OR EXISTS (SELECT 1 FROM "close_detail_inputs" AS q WHERE ((q."close_revision_id"=NEW."close_revision_id" AND q."instrument_id"=NEW."instrument_id" AND q."detail_revision"=NEW."detail_revision")) AND NOT (q."close_revision_id" IS OLD."close_revision_id" AND q."instrument_id" IS OLD."instrument_id" AND q."detail_revision" IS OLD."detail_revision")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_close_entity_inputs_insert BEFORE INSERT ON "close_entity_inputs" WHEN EXISTS (SELECT 1 FROM "close_entity_inputs" AS q WHERE (q."close_revision_id"=NEW."close_revision_id" AND q."change_log_id"=NEW."change_log_id")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_close_entity_inputs_update BEFORE UPDATE ON "close_entity_inputs" WHEN NEW."close_revision_id" IS NOT OLD."close_revision_id" OR NEW."change_log_id" IS NOT OLD."change_log_id" OR EXISTS (SELECT 1 FROM "close_entity_inputs" AS q WHERE ((q."close_revision_id"=NEW."close_revision_id" AND q."change_log_id"=NEW."change_log_id")) AND NOT (q."close_revision_id" IS OLD."close_revision_id" AND q."change_log_id" IS OLD."change_log_id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_close_lot_allocations_insert BEFORE INSERT ON "close_lot_allocations" WHEN EXISTS (SELECT 1 FROM "close_lot_allocations" AS q WHERE (q."close_revision_id"=NEW."close_revision_id" AND q."disposal_event_id"=NEW."disposal_event_id" AND q."lot_id"=NEW."lot_id")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_close_lot_allocations_update BEFORE UPDATE ON "close_lot_allocations" WHEN NEW."close_revision_id" IS NOT OLD."close_revision_id" OR NEW."disposal_event_id" IS NOT OLD."disposal_event_id" OR NEW."lot_id" IS NOT OLD."lot_id" OR EXISTS (SELECT 1 FROM "close_lot_allocations" AS q WHERE ((q."close_revision_id"=NEW."close_revision_id" AND q."disposal_event_id"=NEW."disposal_event_id" AND q."lot_id"=NEW."lot_id")) AND NOT (q."close_revision_id" IS OLD."close_revision_id" AND q."disposal_event_id" IS OLD."disposal_event_id" AND q."lot_id" IS OLD."lot_id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_close_quote_inputs_insert BEFORE INSERT ON "close_quote_inputs" WHEN EXISTS (SELECT 1 FROM "close_quote_inputs" AS q WHERE (q."close_revision_id"=NEW."close_revision_id" AND q."quote_id"=NEW."quote_id")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_close_quote_inputs_update BEFORE UPDATE ON "close_quote_inputs" WHEN NEW."close_revision_id" IS NOT OLD."close_revision_id" OR NEW."quote_id" IS NOT OLD."quote_id" OR EXISTS (SELECT 1 FROM "close_quote_inputs" AS q WHERE ((q."close_revision_id"=NEW."close_revision_id" AND q."quote_id"=NEW."quote_id")) AND NOT (q."close_revision_id" IS OLD."close_revision_id" AND q."quote_id" IS OLD."quote_id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_close_revisions_insert BEFORE INSERT ON "close_revisions" WHEN EXISTS (SELECT 1 FROM "close_revisions" AS q WHERE (q."id"=NEW."id") OR (q."close_id"=NEW."close_id" AND q."id"=NEW."id") OR (q."close_id"=NEW."close_id" AND q."sequence"=NEW."sequence")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
CREATE TRIGGER guard_close_revisions_update BEFORE UPDATE ON "close_revisions" WHEN NEW."id" IS NOT OLD."id" OR EXISTS (SELECT 1 FROM "close_revisions" AS q WHERE ((q."id"=NEW."id") OR (q."close_id"=NEW."close_id" AND q."id"=NEW."id") OR (q."close_id"=NEW."close_id" AND q."sequence"=NEW."sequence")) AND NOT (q."id" IS OLD."id")) BEGIN SELECT RAISE(ABORT, 'protected_identity_conflict'); END;
CREATE TRIGGER guard_currencies_insert BEFORE INSERT ON "currencies" WHEN EXISTS (SELECT 1 FROM "currencies" AS q WHERE (q."code"=NEW."code")) BEGIN SELECT RAISE(ABORT, 'existing_protected_identity'); END;
